/// Views the `enabled` prop turned off. AppKit has no NSView-level enabled,
/// so a non-control handle keeps its flag here, which is also what
/// Automation.swift's a11y probe reads back for those nodes. Purged from
/// Backend.swift's ndPurgeNodeRegistries, like every other
/// ObjectIdentifier-keyed table.
nonisolated(unsafe) var ndDisabledViews: Set<ObjectIdentifier> = []

func ndViewIsEnabled(_ view: NSView) -> Bool { !ndDisabledViews.contains(ObjectIdentifier(view)) }

/// The universal `enabled` prop. NSControl owns the real thing, and the a11y
/// probe reads it straight back; a composite handle passes it down to the
/// controls it is built from. A plain container has no AppKit peer at all,
/// so it dims and reports disabled but still routes clicks to its children —
/// gtk_widget_set_sensitive propagates through the subtree and AppKit has
/// nothing that does.
@MainActor func ndApplyEnabled(_ view: NSView, _ on: Bool) {
    if on {
        ndDisabledViews.remove(ObjectIdentifier(view))
    } else {
        ndDisabledViews.insert(ObjectIdentifier(view))
    }
    // A hosted leaf's SwiftUI body reads this back through NDLeafState, not
    // NSControl.isEnabled — it may wrap no NSControl at all (SwiftUILeaves.swift).
    // NDLeafChromeHosting also covers Banner, which reuses NDLeafChrome
    // without subclassing NDHostedLeaf (Banners.swift).
    if ndHostedLeafSetEnabled(view, on) { return }
    if let control = view as? NSControl {
        control.isEnabled = on
        return
    }
    if let number = view as? NDNumberInputView {
        number.field.isEnabled = on
        number.stepper.isEnabled = on
        return
    }
    if let scroll = view as? NSScrollView {
        if let control = scroll.documentView as? NSControl {
            control.isEnabled = on
            return
        }
        if let text = scroll.documentView as? NSTextView {
            text.isEditable = on
            text.isSelectable = on
            return
        }
    }
    view.alphaValue = on ? 1.0 : 0.5
}

/// The universal `tooltip` prop. A hosted leaf applies it as SwiftUI `.help()`
/// (SwiftUILeaves.swift) — the hosting view's own tracking area does not
/// reliably fire hover callbacks over the SwiftUI content drawn inside it.
@MainActor func ndApplyTooltip(_ view: NSView, _ tip: String) {
    if ndHostedLeafSetTooltip(view, tip) { return }
    view.toolTip = tip.isEmpty ? nil : tip
}

/// The universal `focus` command: AppKit focus is first-responder status on
/// the view's own window. Composite and scroll-shaped handles hand back the
/// view that can actually take it. A hosted leaf also bumps its SwiftUI
/// `@FocusState` token (SwiftUILeaves.swift) — AppKit's first-responder
/// machinery has no way to reach into a pure-SwiftUI control on its own.
@MainActor func ndFocusView(_ view: NSView) {
    if ndHostedLeafFocus(view) { return }
    var target = view
    if let number = view as? NDNumberInputView {
        target = number.field
    } else if let scroll = view as? NSScrollView, let document = scroll.documentView {
        target = document
    }
    guard let window = target.window ?? ndWindow(for: target) else { return }
    window.makeFirstResponder(target)
}

