    override func cancelOperation(_ sender: Any?) { handle?.userDismissed() }
}

/// An overlay's single content child, inset by the standard window margin so
/// its controls never sit flush against the frame.
func ndOverlaySetChild(_ container: NSView, _ child: NSView) {
    container.subviews.forEach { $0.removeFromSuperview() }
    child.translatesAutoresizingMaskIntoConstraints = false
    container.addSubview(child)
    let inset = ndWindowContentMargin
    NSLayoutConstraint.activate([
        child.leadingAnchor.constraint(equalTo: container.leadingAnchor, constant: inset),
        child.trailingAnchor.constraint(equalTo: container.trailingAnchor, constant: -inset),
        child.topAnchor.constraint(equalTo: container.topAnchor, constant: inset),
        child.bottomAnchor.constraint(equalTo: container.bottomAnchor, constant: -inset),
    ])
}

/// `<dialog>`: the node's tracked handle is a host-only NSView (the Popover
/// idiom — it never enters the view hierarchy). The content lives in its own
/// NSWindow, which AppKit runs as a sheet on the tree parent's window: the
/// platform's arbitrary-content modal.
final class NDDialogHandleView: NSView, NDOverlayDismissable {
    var nodeID: UInt32 = 0
    var closable = true
    var contentWidth = 0
    var contentHeight = 0
    var title = "" {
        didSet { layoutContent() }
    }
    let contentContainer = FlippedView()
    private weak var anchor: NSView?
    private weak var child: NSView?
    private var sheet: NDModalSheetWindow?
    private var pendingOpen = false

    /// Cross-cutting append guard: the tree parent names the window to sheet on.
    func attachToParent(_ parent: NSView) {
        anchor = parent
        if pendingOpen {
            pendingOpen = false
            applyOpen(true)
        }
    }

    func detachFromParent(_ parent: NSView) {
        applyOpen(false)
        if anchor === parent { anchor = nil }
    }

    func applyOpen(_ open: Bool) {
        if open { present() } else { dismiss() }
    }

    func userDismissed() {
        guard closable else { return }
        ndEmitEvent(nodeID, "closed", "{}")
    }

    func setChild(_ child: NSView) {
        self.child = child
        layoutContent()
    }

    func clearChild(_ child: NSView) {
        if self.child === child { self.child = nil }
        if child.superview === contentContainer { child.removeFromSuperview() }
        layoutContent()
    }

    /// The title belongs in the sheet's CONTENT on the Mac, set as a bold
    /// headline above the app's own controls — NSAlert's layout, and what the
    /// platform's other arbitrary-content modals look like. The window title
    /// bar is not it: `.fullSizeContentView` puts the content over the title
    /// bar, so `window.title` rendered nowhere and the sheet came up untitled.
    private func layoutContent() {
        contentContainer.subviews.forEach { $0.removeFromSuperview() }
        guard let child else { return }
        let inset = ndWindowContentMargin
        child.translatesAutoresizingMaskIntoConstraints = false
        contentContainer.addSubview(child)
        var constraints = [
            child.leadingAnchor.constraint(equalTo: contentContainer.leadingAnchor, constant: inset),
            child.trailingAnchor.constraint(equalTo: contentContainer.trailingAnchor, constant: -inset),
            child.bottomAnchor.constraint(equalTo: contentContainer.bottomAnchor, constant: -inset),
        ]
        if title.isEmpty {
            constraints.append(child.topAnchor.constraint(equalTo: contentContainer.topAnchor, constant: inset))
        } else {
            let headline = NSTextField(labelWithString: title)
            headline.font = .preferredFont(forTextStyle: .headline, options: [:])
            headline.alignment = .center
            headline.translatesAutoresizingMaskIntoConstraints = false
            contentContainer.addSubview(headline)
            constraints.append(contentsOf: [
                headline.leadingAnchor.constraint(equalTo: contentContainer.leadingAnchor, constant: inset),
                headline.trailingAnchor.constraint(equalTo: contentContainer.trailingAnchor, constant: -inset),
                headline.topAnchor.constraint(equalTo: contentContainer.topAnchor, constant: inset),
                child.topAnchor.constraint(equalTo: headline.bottomAnchor, constant: ndStandardSpacing),
            ])
        }
        NSLayoutConstraint.activate(constraints)
    }

    private func present() {
        guard sheet == nil else { return }
        guard let parent = anchor?.window ?? anchor.flatMap({ ndWindow(for: $0) }) else {
            // Not realized yet (create-time open, or an attach that ran before
            // the window materialized): retry next turn, else keep the flag for
            // attachToParent to honor.
            pendingOpen = true
            if anchor != nil {
                DispatchQueue.main.async { [weak self] in
                    guard let self, self.pendingOpen else { return }
                    self.pendingOpen = false
                    self.present()
                }
            }
            return
        }
        let fitting = contentContainer.fittingSize
        let size = NSSize(
            width: contentWidth > 0 ? CGFloat(contentWidth) : max(fitting.width, 360),
            height: contentHeight > 0 ? CGFloat(contentHeight) : max(fitting.height, 140))
        let window = NDModalSheetWindow(
            contentRect: NSRect(origin: .zero, size: size),
            styleMask: [.titled, .fullSizeContentView],
            backing: .buffered, defer: true)
        window.handle = self
        window.titlebarAppearsTransparent = true
        window.titleVisibility = .hidden  // the title is drawn in the content
        window.isReleasedWhenClosed = false
        window.contentView = contentContainer
        sheet = window
        parent.beginSheet(window) { [weak self] _ in self?.sheet = nil }
    }

    private func dismiss() {
        pendingOpen = false
        guard let window = sheet else { return }
        if let parent = window.sheetParent {
            parent.endSheet(window)  // the completion handler clears `sheet`
        } else {
            sheet = nil
        }
    }
}

