    private var sheet: NDModalSheetWindow?
    private var pendingOpen = false

    func attachToParent(_ parent: NSView) {
        anchor = parent
        if pendingOpen {
            pendingOpen = false
            applyOpen(true)
        }
    }

    func detachFromParent(_ parent: NSView) {
        applyOpen(false)
        if anchor === parent { anchor = nil }
    }

    func applyOpen(_ open: Bool) {
        if open { present() } else { dismiss() }
    }

    func userDismissed() {
        ndEmitEvent(nodeID, "closed", "{}")
    }

    func setChild(_ child: NSView) { ndOverlaySetChild(contentContainer, child) }

    func clearChild(_ child: NSView) {
        if child.superview === contentContainer { child.removeFromSuperview() }
    }

    private func present() {
        guard sheet == nil else { return }
        guard let parent = anchor?.window ?? anchor.flatMap({ ndWindow(for: $0) }) else {
            pendingOpen = true
            if anchor != nil {
                DispatchQueue.main.async { [weak self] in
                    guard let self, self.pendingOpen else { return }
                    self.pendingOpen = false
                    self.present()
                }
            }
            return
        }
        let fitting = contentContainer.fittingSize
        let frame = NSRect(
            origin: .zero,
            size: NSSize(width: max(fitting.width, 360),
                         height: max(fitting.height, 120)))
        let window = NDModalSheetWindow(
            contentRect: frame,
            styleMask: [.titled, .fullSizeContentView],
            backing: .buffered, defer: true)
        window.handle = self
        window.titlebarAppearsTransparent = true
        window.titleVisibility = .hidden
        window.isReleasedWhenClosed = false
        window.contentView = contentContainer
        sheet = window
        parent.beginSheet(window) { [weak self] _ in self?.sheet = nil }
    }

    private func dismiss() {
        pendingOpen = false
        guard let window = sheet else { return }
        if let parent = window.sheetParent {
            parent.endSheet(window)  // the completion handler clears `sheet`
        } else {
            sheet = nil
        }
    }
}

func ndMakeDialog(_ props: [String: Any]) -> NSView {
    let handle = NDDialogHandleView()
    handle.title = propStr(props, "title") ?? ""
    handle.closable = propBool(props, "closable") ?? true
    handle.contentWidth = propInt(props, "contentWidth") ?? 0
    handle.contentHeight = propInt(props, "contentHeight") ?? 0
    if propBool(props, "open") ?? false { handle.applyOpen(true) } // no anchor yet: recorded as pending
    return handle
}

func ndMakeSheet(_ props: [String: Any]) -> NSView {
    let handle = NDSheetHandleView()
    handle.edge = propStr(props, "edge") ?? "bottom"
    handle.size = propInt(props, "size") ?? 320
    if propBool(props, "open") ?? false { handle.applyOpen(true) }
    return handle
}

func ndOverlayConnect(_ view: NSView, nodeID: UInt32) {
    (view as? NDDialogHandleView)?.nodeID = nodeID
    (view as? NDSheetHandleView)?.nodeID = nodeID
}

// MARK: - cross-cutting structural guards (the Popover pair's peers: an
// overlay handle records its tree parent instead of being packed into it).

func ndOverlayStructuralAttach(_ child: NSView, _ parent: NSView) -> Bool {
    if let dialog = child as? NDDialogHandleView {
        dialog.attachToParent(parent)
        return true
    }
    if let sheet = child as? NDSheetHandleView {
        sheet.attachToParent(parent)
        return true
    }
    return false
}

func ndOverlayStructuralDetach(_ child: NSView, _ parent: NSView) -> Bool {
    if let dialog = child as? NDDialogHandleView {
        dialog.detachFromParent(parent)
        return true
    }
    if let sheet = child as? NDSheetHandleView {
        sheet.detachFromParent(parent)
        return true
    }
    return false
}

/// Generated structural Dialog/Sheet arms (the overlay's OWN content child).
func ndOverlaySetContent(_ parent: NSView, _ child: NSView) {
    (parent as? NDDialogHandleView)?.setChild(child)
    (parent as? NDSheetHandleView)?.setChild(child)
}

func ndOverlayClearContent(_ parent: NSView, _ child: NSView) {
    (parent as? NDDialogHandleView)?.clearChild(child)
    (parent as? NDSheetHandleView)?.clearChild(child)
}

// ---- RichText: Markdown -> NSAttributedString in a selectable NSTextView ----

/// The `<richtext>` Markdown subset, parsed identically on both backends:
/// ATX headings (`#` to `######`), paragraphs (soft-wrapped lines join with a
/// space), `-`/`*`/`+` bullet lists, fenced code blocks, and the inline runs
/// `**bold**`, `__bold__`, `*italic*`, `_italic_`, `` `code` `` and
/// `[label](href)`. Everything else lands as literal text: no ordered lists,
/// block quotes, tables, images, HTML, reference links, setext headings or
/// horizontal rules. Emphasis does not nest, and a link's label is one run.
struct NDRichRun {
    var text: String
    var bold = false
    var italic = false
    var code = false
    var heading = 0
    var href: String? = nil
}

func ndRichRunAttributed(_ run: NDRichRun) -> NSAttributedString {
    let body = NSFont.systemFontSize
    var font: NSFont
    if run.heading > 0 {
        let bump: CGFloat = run.heading == 1 ? 9 : (run.heading == 2 ? 5 : 2)
        font = .systemFont(ofSize: body + bump, weight: .bold)
    } else if run.code {
        font = .monospacedSystemFont(ofSize: body - 1, weight: .regular)
    } else {
        font = .systemFont(ofSize: body, weight: run.bold ? .bold : .regular)
    }
    if run.italic, !run.code {
        let traits = font.fontDescriptor.symbolicTraits.union(.italic)
        font = NSFont(descriptor: font.fontDescriptor.withSymbolicTraits(traits), size: font.pointSize) ?? font
    }
    var attrs: [NSAttributedString.Key: Any] = [.font: font, .foregroundColor: NSColor.labelColor]
    // A plain String link: AppKit hands the same value back to the delegate,
    // so an href that is not a URL still round-trips.
    if let href = run.href { attrs[.link] = href }
    return NSAttributedString(string: run.text, attributes: attrs)
}

private struct NDRichLink {
    let label: String
    let href: String
    let end: Int
}

private func ndRichParseLink(_ ch: [Character], _ start: Int) -> NDRichLink? {
    guard let closeBracket = ch[(start + 1)...].firstIndex(of: "]"),
          closeBracket + 1 < ch.count, ch[closeBracket + 1] == "(",
          let closeParen = ch[(closeBracket + 2)...].firstIndex(of: ")") else { return nil }
    return NDRichLink(
        label: String(ch[(start + 1)..<closeBracket]),
        href: String(ch[(closeBracket + 2)..<closeParen]),
        end: closeParen + 1)
}

private func ndRichFindMarker(_ ch: [Character], _ from: Int, _ marker: Character, _ length: Int) -> Int? {
    var i = from
    while i + length <= ch.count {
        if ch[i] == marker, length == 1 || ch[i + 1] == marker { return i }
        i += 1
    }
    return nil
}

/// Inline scan over one block's text. `base` carries the block-level look
/// (a heading's size and weight), which every run inherits.
func ndRichAppendInline(_ out: NSMutableAttributedString, _ text: String, _ base: NDRichRun) {
    let ch = Array(text)
    var i = 0
    var plain = 0
    func flush(_ end: Int) {
        guard end > plain else { return }
        var run = base
        run.text = String(ch[plain..<end])
        out.append(ndRichRunAttributed(run))
    }
    while i < ch.count {
        if ch[i] == "`", let close = ch[(i + 1)...].firstIndex(of: "`") {
            flush(i)
            var run = base
            run.code = true
            run.text = String(ch[(i + 1)..<close])
            out.append(ndRichRunAttributed(run))
            i = close + 1
            plain = i
            continue
        }
        if ch[i] == "[", let link = ndRichParseLink(ch, i) {
            flush(i)
            var run = base
            run.href = link.href
            run.text = link.label
            out.append(ndRichRunAttributed(run))
            i = link.end
            plain = i
            continue
        }
        if ch[i] == "*" || ch[i] == "_" {
            let marker = ch[i]
            let strong = i + 1 < ch.count && ch[i + 1] == marker
            let markerLength = strong ? 2 : 1
            let bodyStart = i + markerLength
            if bodyStart < ch.count, let close = ndRichFindMarker(ch, bodyStart, marker, markerLength), close > bodyStart {
                flush(i)
                var run = base
                if strong { run.bold = true } else { run.italic = true }
                run.text = String(ch[bodyStart..<close])
                out.append(ndRichRunAttributed(run))
                i = close + markerLength
                plain = i
                continue
            }
        }
        i += 1
    }
    flush(ch.count)
}

private func ndRichBulletBody(_ line: String) -> String? {
    guard line.count >= 2 else { return nil }
    let ch = Array(line)
    guard ch[0] == "-" || ch[0] == "*" || ch[0] == "+", ch[1] == " " else { return nil }
    return String(ch[2...]).trimmingCharacters(in: .whitespaces)
}

func ndMarkdownAttributed(_ markdown: String) -> NSAttributedString {
    let out = NSMutableAttributedString()
    let lines = markdown.components(separatedBy: "\n").map { $0.hasSuffix("\r") ? String($0.dropLast()) : $0 }
    var first = true
    func gap() {
        if first { first = false } else { out.append(NSAttributedString(string: "\n\n")) }
    }
    var i = 0
    while i < lines.count {
        let line = lines[i].trimmingCharacters(in: .whitespaces)
        if line.isEmpty { i += 1; continue }
        if line.hasPrefix("```") {
            i += 1
            var code: [String] = []
            while i < lines.count, !lines[i].trimmingCharacters(in: .whitespaces).hasPrefix("```") {
                // Four spaces per line is the indent, matching the GTK peer:
                // the fence is already monospaced, so nothing else is needed.
                code.append("    " + lines[i])
                i += 1
            }
            if i < lines.count { i += 1 }  // closing fence
            gap()
            out.append(ndRichRunAttributed(NDRichRun(text: code.joined(separator: "\n"), code: true)))
            continue
        }
        if line.hasPrefix("#") {
            let hashes = line.prefix(while: { $0 == "#" }).count
            let ch = Array(line)
            if hashes <= 6, hashes < ch.count, ch[hashes] == " " {
                gap()
                var base = NDRichRun(text: "")
                base.heading = hashes
                ndRichAppendInline(out, String(ch[(hashes + 1)...]).trimmingCharacters(in: .whitespaces), base)
                i += 1
                continue
            }
        }
        if let body = ndRichBulletBody(line) {
            gap()
            out.append(ndRichRunAttributed(NDRichRun(text: "\u{2022} ")))
            ndRichAppendInline(out, body, NDRichRun(text: ""))
            i += 1
            while i < lines.count, let next = ndRichBulletBody(lines[i].trimmingCharacters(in: .whitespaces)) {
                out.append(ndRichRunAttributed(NDRichRun(text: "\n\u{2022} ")))
                ndRichAppendInline(out, next, NDRichRun(text: ""))
                i += 1
            }
            continue
        }
        var paragraph: [String] = []
        while i < lines.count {
            let p = lines[i].trimmingCharacters(in: .whitespaces)
            if p.isEmpty || p.hasPrefix("#") || p.hasPrefix("```") || ndRichBulletBody(p) != nil { break }
            paragraph.append(p)
            i += 1
        }
        gap()
        ndRichAppendInline(out, paragraph.joined(separator: " "), NDRichRun(text: ""))
    }
    return out
}

/// `<richtext>`: a non-editable NSTextView in an NSScrollView (the tracked
/// handle is the scroll view, the TextArea convention). The view is its own
/// delegate so a click on a `.link` run reports the href back as
/// `linkActivated` instead of AppKit opening it.
final class NDRichTextView: NSTextView, NSTextViewDelegate {
    var nodeID: UInt32 = 0

    func textView(_ textView: NSTextView, clickedOnLink link: Any, at charIndex: Int) -> Bool {
        let href = (link as? String) ?? (link as? URL)?.absoluteString ?? ""
        ndEmitEvent(nodeID, "linkActivated", "{\"text\":\(ndJsonString(href))}")
        return true  // handled: the app decides what an href means
    }
}

func ndMakeRichText(_ props: [String: Any]) -> NSView {
    let text = NDRichTextView()
    text.isEditable = false
    text.isSelectable = propBool(props, "selectable") ?? true
    text.drawsBackground = false
    text.textContainerInset = NSSize(width: 4, height: 4)
    text.minSize = NSSize(width: 0, height: 0)
    text.maxSize = NSSize(width: CGFloat.greatestFiniteMagnitude, height: CGFloat.greatestFiniteMagnitude)
    text.isVerticallyResizable = true
    text.isHorizontallyResizable = false
    text.autoresizingMask = [.width]
    text.textContainer?.widthTracksTextView = true
    text.textContainer?.containerSize = NSSize(width: 0, height: CGFloat.greatestFiniteMagnitude)
    text.linkTextAttributes = [
        .foregroundColor: NSColor.linkColor,
        .underlineStyle: NSUnderlineStyle.single.rawValue,
        .cursor: NSCursor.pointingHand,
    ]
    text.delegate = text

    let scroll = NSScrollView()
    scroll.hasVerticalScroller = true
    scroll.drawsBackground = false
    scroll.documentView = text
    // GTK propagates the document's natural height (setPropagateNaturalHeight
    // in ndRichTextCreate); an NSScrollView reports no intrinsic size at all,
    // so in a content-sized column the whole widget laid out at zero height
    // and rendered nothing. Same height floor TextArea takes, same priority.
    scroll.frame.size.height = 120
    let floor_ = scroll.heightAnchor.constraint(greaterThanOrEqualToConstant: 120)
    floor_.priority = NSLayoutConstraint.Priority(999)
    floor_.isActive = true
    ndRichTextSetMarkdown(scroll, propStr(props, "markdown") ?? "")
    return scroll
}

private func ndRichTextInner(_ view: NSView) -> NDRichTextView? {
    (view as? NSScrollView)?.documentView as? NDRichTextView
}

/// Generated ndApplyProps RichText.markdown arm.
func ndRichTextSetMarkdown(_ view: NSView, _ markdown: String) {
    guard let text = ndRichTextInner(view) else { return }
    text.textStorage?.setAttributedString(ndMarkdownAttributed(markdown))
}

/// Generated ndApplyProps RichText.selectable arm. AppKit routes link clicks
/// through the selection machinery, so an unselectable view has inert links
/// by design.
func ndRichTextSetSelectable(_ view: NSView, _ selectable: Bool) {
    ndRichTextInner(view)?.isSelectable = selectable
}

/// Generated ndConnectEvents RichText arm.
func ndRichTextConnect(_ view: NSView, nodeID: UInt32) {
    ndRichTextInner(view)?.nodeID = nodeID
}

// ---- ProgressCircle / ProgressBar / Spinner: SwiftUI-bodied leaves --------

/// `<progresscircle>`: a trimmed `Circle` stroked over a track ring.
///
/// SwiftUI's `Gauge` in `.accessoryCircularCapacity` looks like the right
/// control and is not: it is a watch-complication style with fixed metrics
/// that draws at 58x58 whatever frame it is given, so a `.frame(32, 32)`
/// clipped nothing and neighbouring rings overlapped each other and bled out
/// of their row. Two shapes bound by their own frame cannot do that, and they
/// honour `lineWidth`, which that style silently dropped. The GTK peer draws
/// the identical arc with Cairo for the same reason (neither toolkit ships a
/// determinate ring).
final class NDProgressCircleView: NDHostedLeaf {
    /// The label has to fit INSIDE the ring, so a ring carrying one is drawn
    /// larger. Same two diameters as the GTK peer.
    private static let plainDiameter: CGFloat = 28
    private static let labeledDiameter: CGFloat = 40

    private var fraction: Double = 0
    private var lineWidth: Int = 3
    private var showLabel = false

    func apply(fraction: Double?, lineWidth: Int?, showLabel: Bool?) {
        if let fraction { self.fraction = fraction }
        if let lineWidth { self.lineWidth = lineWidth }
        if let showLabel { self.showLabel = showLabel }
        refreshLeaf()
    }

    override func leafContent() -> AnyView {
        let value = min(max(fraction, 0), 1)
        let diameter = showLabel ? Self.labeledDiameter : Self.plainDiameter
        // A stroke straddles the path, so half of it falls outside the circle:
        // inset by that half or the ring's outer edge overflows the frame.
        let stroke = min(max(CGFloat(lineWidth), 1), diameter / 3)
        let showLabel = showLabel
        return AnyView(
            ZStack {
                Circle()
                    .stroke(Color(nsColor: .separatorColor), lineWidth: stroke)
                Circle()
                    .trim(from: 0, to: value)
                    .stroke(
                        Color(nsColor: .controlAccentColor),
                        style: StrokeStyle(lineWidth: stroke, lineCap: .round))
                    .rotationEffect(.degrees(-90))  // 12 o'clock, clockwise
                if showLabel {
                    Text("\(Int((value * 100).rounded()))%")
                        .font(.system(size: diameter * 0.28, weight: .medium))
                        .monospacedDigit()
                        .foregroundStyle(Color(nsColor: .secondaryLabelColor))
                        .lineLimit(1)
                        .minimumScaleFactor(0.6)
                        .padding(.horizontal, stroke)
                }
            }
            .padding(stroke / 2)
            .frame(width: diameter, height: diameter)
            .accessibilityHidden(true)
        )
    }

    override var ndA11yValueJSON: String { "\(fraction)" }
}

func makeProgressCircle(_ props: [String: Any]) -> NSView {
    let circle = NDProgressCircleView()
    circle.apply(
        fraction: propDouble(props, "fraction") ?? 0,
        lineWidth: propInt(props, "lineWidth") ?? 3,
        showLabel: propBool(props, "showLabel") ?? false)
    return circle
}

/// Generated ndApplyProps ProgressCircle arm — merged apply.
func ndProgressCircleApply(_ view: NSView, _ props: [String: Any]) {
    (view as? NDProgressCircleView)?.apply(
        fraction: propDouble(props, "fraction"),
        lineWidth: propInt(props, "lineWidth"),
        showLabel: propBool(props, "showLabel"))
}

/// `<progressbar>`: SwiftUI `ProgressView`, the system determinate bar.
final class NDProgressBarView: NDHostedLeaf {
