/// `<segmentedcontrol>`: SwiftUI `Picker` in its `.segmented` style, the
/// system segmented control. `options` is create-only (Select accepts the
/// same limitation) since a Picker enumerates its labeled content once, at
/// construction.
final class NDSegmentedControlView: NDHostedLeaf {
    private var options: [String] = []
    private var selectedIndex = 0

    func applyCreate(options: [String], selectedIndex: Int) {
        self.options = options
        self.selectedIndex = selectedIndex
        refreshLeaf()
    }

    /// React-driven `selectedIndex` write, echo-suppressed like every other
    /// controlled prop.
    func setSelectedIndexFromProps(_ idx: Int) {
        guard idx != selectedIndex else { return }
        withEchoSuppressed(self) { setSelectedIndex(idx, emit: false) }
    }

    private func setSelectedIndex(_ idx: Int, emit: Bool) {
        selectedIndex = idx
        refreshLeaf()
        if emit, !ndIsEchoSuppressed(self) {
            ndEmitEvent(ndNodeID, "selectionChanged", "{\"index\":\(idx)}")
        }
    }

    override func leafContent() -> AnyView {
        AnyView(
            Picker("", selection: Binding(
                get: { [weak self] in self?.selectedIndex ?? 0 },
                set: { [weak self] in self?.setSelectedIndex($0, emit: true) }
            )) {
                ForEach(Array(options.enumerated()), id: \.offset) { idx, label in
                    Text(label).tag(idx)
                }
            }
            .pickerStyle(.segmented)
            .labelsHidden())
    }

    override var ndA11yValueJSON: String { "\(selectedIndex)" }
}

func ndSegmentedControlConnect(_ view: NSView, nodeID: UInt32) {
    (view as? NDSegmentedControlView)?.ndNodeID = nodeID
}

/// `<slider>`: SwiftUI `Slider`, the system track. `snapsToStep` is computed
/// once at create time the same way the old NSSlider tick-mark gate was: the
/// schema default (1) applied literally to a narrow range (min 0, max 1, say)
/// would turn a continuous track into a two-position toggle, so only a step
/// explicitly set away from the default snaps.
final class NDSliderView: NDHostedLeaf {
    private var minValue: Double = 0
    private var maxValue: Double = 100
    private var step: Double = 0
    private var value: Double = 0
    private(set) var vertical = false

    func applyCreate(min: Double, max: Double, step: Double, snapsToStep: Bool, value: Double, vertical: Bool) {
        minValue = min
        maxValue = max
        self.step = snapsToStep ? step : 0
        self.value = value
        self.vertical = vertical
        refreshLeaf()
    }

    /// React-driven `value` write, echo-suppressed like every other
    /// controlled prop.
    func setValueFromProps(_ v: Double) {
        guard abs(v - value) > 1e-9 else { return }
        withEchoSuppressed(self) { setValue(v, emit: false) }
    }

    /// `semanticSetValue`'s Slider arm (Automation.swift): a driven write
    /// behaves like a user drag, not a React update — it emits.
    func driveValue(_ v: Double) { setValue(v, emit: true) }

    private func setValue(_ v: Double, emit: Bool) {
        value = v
        refreshLeaf()
        if emit, !ndIsEchoSuppressed(self) {
            ndEmitEvent(ndNodeID, "valueChanged", "{\"value\":\(v)}")
        }
    }

    override func leafContent() -> AnyView {
        let binding = Binding<Double>(
            get: { [weak self] in self?.value ?? 0 },
            set: { [weak self] in self?.setValue($0, emit: true) })
        let track: AnyView = step > 0
            ? AnyView(Slider(value: binding, in: minValue...maxValue, step: step))
            : AnyView(Slider(value: binding, in: minValue...maxValue))
        guard vertical else { return track }
        // SwiftUI has no vertical Slider axis on macOS: lay the track out
        // horizontally at a fixed length, then rotate and re-frame it into a
        // vertical footprint — the standard SwiftUI idiom, and, like the
        // schema notes, a fixed (not fill-height) length.
        return AnyView(track.frame(width: 160).rotationEffect(.degrees(-90)).frame(width: 24, height: 160))
    }

    override var ndA11yValueJSON: String { "\(value)" }
}

func ndSliderConnect(_ view: NSView, nodeID: UInt32) {
    (view as? NDSliderView)?.ndNodeID = nodeID
}

/// `<switch>`: SwiftUI `Toggle` in its `.switch` style, the system toggle.
final class NDSwitchView: NDHostedLeaf {
    private(set) var checked = false

    func applyCreate(checked: Bool) {
        self.checked = checked
        refreshLeaf()
    }

    /// React-driven `checked` write, echo-suppressed like every other
    /// controlled prop.
    func setCheckedFromProps(_ c: Bool) {
        guard c != checked else { return }
        withEchoSuppressed(self) { setChecked(c, emit: false) }
    }

    /// `semanticSetValue`'s Switch arm: a driven write behaves like a user
    /// tap, not a React update — it emits.
    func driveChecked(_ c: Bool) { setChecked(c, emit: true) }

    private func setChecked(_ c: Bool, emit: Bool) {
        checked = c
        refreshLeaf()
        if emit, !ndIsEchoSuppressed(self) {
            ndEmitEvent(ndNodeID, "toggled", "{\"checked\":\(c)}")
        }
    }

    override func leafContent() -> AnyView {
        AnyView(
            Toggle("", isOn: Binding(
                get: { [weak self] in self?.checked ?? false },
                set: { [weak self] in self?.setChecked($0, emit: true) }
            ))
            .toggleStyle(.switch)
            .labelsHidden())
    }

    override var ndA11yValueJSON: String { checked ? "true" : "false" }
}

func ndSwitchConnect(_ view: NSView, nodeID: UInt32) {
    (view as? NDSwitchView)?.ndNodeID = nodeID
}

/// `<checkbox>`: SwiftUI `Toggle` in its `.checkbox` style, the system
/// checkbox — same shape as NDSwitchView, plus the label the checkbox draws
/// beside its box.
final class NDCheckboxView: NDHostedLeaf {
    private(set) var checked = false
    private var label = ""

    func applyCreate(checked: Bool, label: String) {
        self.checked = checked
        self.label = label
        refreshLeaf()
    }

    func setLabel(_ label: String) {
        self.label = label
        refreshLeaf()
    }

    func setCheckedFromProps(_ c: Bool) {
        guard c != checked else { return }
        withEchoSuppressed(self) { setChecked(c, emit: false) }
    }

    func driveChecked(_ c: Bool) { setChecked(c, emit: true) }

    private func setChecked(_ c: Bool, emit: Bool) {
        checked = c
        refreshLeaf()
        if emit, !ndIsEchoSuppressed(self) {
            ndEmitEvent(ndNodeID, "toggled", "{\"checked\":\(c)}")
        }
    }

    override func leafContent() -> AnyView {
        AnyView(
            Toggle(label, isOn: Binding(
                get: { [weak self] in self?.checked ?? false },
                set: { [weak self] in self?.setChecked($0, emit: true) }
            ))
            .toggleStyle(.checkbox))
    }

    override var ndA11yValueJSON: String { checked ? "true" : "false" }
}

func ndCheckboxConnect(_ view: NSView, nodeID: UInt32) {
    (view as? NDCheckboxView)?.ndNodeID = nodeID
}

/// `<skeleton>`: a CAGradientLayer whose stop locations animate, which is the
/// shimmer every AppKit app builds this out of.
final class NDSkeletonView: NSView {
    private let gradient = CAGradientLayer()
    var animated = true { didSet { syncAnimation() } }
    var contentWidth = 0 { didSet { invalidateIntrinsicContentSize() } }
    var contentHeight = 16 { didSet { invalidateIntrinsicContentSize() } }
    var radius = 6 {
        didSet {
            layer?.cornerRadius = CGFloat(max(radius, 0))
            gradient.cornerRadius = CGFloat(max(radius, 0))
        }
    }

    override var intrinsicContentSize: NSSize {
        NSSize(
            width: contentWidth > 0 ? CGFloat(contentWidth) : NSView.noIntrinsicMetric,
            height: CGFloat(max(contentHeight, 1)))
    }

    init() {
        super.init(frame: .zero)
        wantsLayer = true
        layer?.masksToBounds = true
        layer?.cornerRadius = 6
        gradient.cornerRadius = 6
        gradient.startPoint = CGPoint(x: 0, y: 0.5)
        gradient.endPoint = CGPoint(x: 1, y: 0.5)
        gradient.locations = [0, 0.5, 1]
        layer?.addSublayer(gradient)
        applyColors()
        syncAnimation()
    }

    required init?(coder: NSCoder) { fatalError("NDSkeletonView is code-only") }

    override func layout() {
        super.layout()
        CATransaction.begin()
        CATransaction.setDisableActions(true)
        gradient.frame = bounds
        CATransaction.commit()
    }

    override func viewDidChangeEffectiveAppearance() {
        super.viewDidChangeEffectiveAppearance()
        applyColors()
    }

    private func applyColors() {
        effectiveAppearance.performAsCurrentDrawingAppearance {
            let base = NSColor.labelColor.withAlphaComponent(0.10).cgColor
            let peak = NSColor.labelColor.withAlphaComponent(0.22).cgColor
            gradient.colors = [base, peak, base]
        }
    }

    /// The OS switch outranks the prop: reduce-motion means a flat block,
    /// never a shimmer (GTK peer: gtk-enable-animations).
    private func syncAnimation() {
        gradient.removeAnimation(forKey: "ndSkeletonShimmer")
        gradient.locations = [0, 0.5, 1]
        guard animated, !NSWorkspace.shared.accessibilityDisplayShouldReduceMotion else { return }
        let sweep = CABasicAnimation(keyPath: "locations")
        sweep.fromValue = [-1.0, -0.5, 0.0]
        sweep.toValue = [1.0, 1.5, 2.0]
        sweep.duration = 1.4
        sweep.repeatCount = .infinity
        gradient.add(sweep, forKey: "ndSkeletonShimmer")
    }
}

func ndMakeSkeleton(_ props: [String: Any]) -> NSView {
    let skeleton = NDSkeletonView()
    skeleton.contentWidth = propInt(props, "width") ?? 0
    skeleton.contentHeight = propInt(props, "height") ?? 16
    skeleton.radius = propInt(props, "radius") ?? 6
    skeleton.animated = propBool(props, "animated") ?? true
    return skeleton
}

/// The AppKit create dispatcher. Every kind goes through `ndCreateWidget`
/// below; this wrapper only adds the universal props no per-widget arm
/// should have to repeat.
@MainActor func ndCreate(_ kind: String, _ propsJson: String) -> NSView? {
    guard let view = ndCreateWidget(kind, propsJson) else { return nil }
    let universal = parseProps(propsJson)
    if let tip = propStr(universal, "tooltip") { ndApplyTooltip(view, tip) }
    if let on = propBool(universal, "enabled") { ndApplyEnabled(view, on) }
    ndDragDropApply(view, universal)
    return view
}

func ndCreateWidget(_ kind: String, _ propsJson: String) -> NSView? {
    let props = parseProps(propsJson)
    if kind == "Window" {
        let content = FlippedView()
        let winW = propInt(props, "defaultWidth") ?? 480
        let winH = propInt(props, "defaultHeight") ?? 320
        let win = NSWindow(contentRect: NSRect(x: 0, y: 0, width: CGFloat(winW), height: CGFloat(winH)), styleMask: [.titled, .closable, .miniaturizable, .resizable, .fullSizeContentView], backing: .buffered, defer: false)
        if let t = propStr(props, "title") { win.title = t }
        win.titlebarAppearsTransparent = true
        // The core (not AppKit) owns window lifetime: close() must never
        // dealloc the window while the retained tree still references it.
        win.isReleasedWhenClosed = false
        win.contentView = content
        ndAutomationApplyWindowPolicy(win) // automation runs float past tiling WMs (Automation.swift)
        gWindow = win
        // toolbarStyle is consumed by NDToolbarManager.attachForSidebar once
        // a headerbar/sidebar attaches the unified toolbar; frameAutosaveName
        // doubles as the toolbar-customization autosave key (HeaderBar.swift).
        ndWindowToolbarStyles[ObjectIdentifier(win)] = propStr(props, "toolbarStyle") ?? "unified"
        ndApplyDensity(win, propStr(props, "density") ?? "standard")
        let manager = NDToolbarManager(autosaveName: propStr(props, "frameAutosaveName"))
        ndWindowToolbarManager = manager
        ndEnsureMenuManager() // M13: install the default NSApp.mainMenu (App/File/Edit/View/Window/Help)
        // Tab-aware presentation (WindowTabs.swift): a `tabGroup` window
        // joins its group's native tab bar via addTabbedWindow; a
        // `presentation="sheet"` window becomes a window-modal sheet on
        // whichever window asked for it; a plain window centers and orders
        // front as before.
        ndWindowTabsPresent(win, tabGroup: propStr(props, "tabGroup"), presentation: propStr(props, "presentation"))
        // After present: a session frame saved under this name must win
        // over the default center()+defaultWidth/Height placement.
        if let fan = propStr(props, "frameAutosaveName") { win.setFrameAutosaveName(fan) }
        return content
    } else if kind == "Box" {
        let stack = NDBoxStackView()
        let vertical = (propStr(props, "orientation") ?? "vertical") == "vertical"
        stack.orientation = vertical ? .vertical : .horizontal
        // -1 is the "platform standard" sentinel (schema default):
        // ndStandardSpacing (8) here, 6 on the GTK peer.
        let spacingRaw = propInt(props, "spacing") ?? -1
        stack.spacing = spacingRaw < 0 ? ndStandardSpacing : CGFloat(spacingRaw)
        stack.alignment = vertical ? .leading : .centerY
        stack.distribution = .gravityAreas
        return stack
    } else if kind == "Label" {
        let text = propStr(props, "text") ?? ""
        let label = NDTextField(labelWithString: text)
        if propBool(props, "ellipsize") ?? false {
            // Truncate instead of forcing the min width to the full text.
            label.lineBreakMode = .byTruncatingTail
            label.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)
        }
        return label
    } else if kind == "Button" {
        let lbl = propStr(props, "label") ?? ""
        let b = NDButton(title: lbl, target: nil, action: nil)
        b.setButtonType(.momentaryPushIn); b.bezelStyle = .rounded
        // Image bytes beat a symbol name: a favicon has no SF Symbol, and this
        // is the only way a browser toolbar can show one.
        if let data = propStr(props, "iconData") {
            ndApplyButtonIconData(b, iconData: data, label: lbl)  // NDShell/Icons.swift (hand-written)
        } else if let icon = propStr(props, "iconName") {
            // Through the update helper, so the name it remembers is seeded
            // here and the first applyProps carrying the same icon is a no-op
            // (NDShell/HeaderBar.swift; the toolbar owner is still nil).
            ndButtonApplyIconName(b, icon)
        }
        switch propStr(props, "labelAlign") ?? "center" {
        case "start": b.alignment = .left
        case "end": b.alignment = .right
        default: break
        }
        if propBool(props, "ellipsize") ?? false {
            b.lineBreakMode = .byTruncatingTail
            b.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)
        }
        if propBool(props, "prominent") ?? false { ndButtonApplyProminent(b, true) }
        if let badge = propStr(props, "badge") { ndButtonApplyBadge(b, badge) }
        ndButtonApplySize(b, propStr(props, "size") ?? "regular")
        return b
    } else if kind == "TextInput" {
        let field = NDTextField(string: propStr(props, "text") ?? "")
        if let ph = propStr(props, "placeholder") { field.placeholderString = ph }
        if let e = propBool(props, "editable") { field.isEditable = e }
        return field
    } else if kind == "TextArea" {
        let scroll = NSScrollView()
        scroll.hasVerticalScroller = true
        scroll.borderType = .bezelBorder
        scroll.drawsBackground = true
        let textView = NSTextView()
        textView.drawsBackground = true
        textView.backgroundColor = .textBackgroundColor
        textView.textContainerInset = NSSize(width: 4, height: 6)
        textView.string = propStr(props, "text") ?? ""
        scroll.documentView = textView
        let minH = propInt(props, "minContentHeight") ?? 120
        if minH > 0 {
            scroll.frame.size.height = CGFloat(minH)
            let floor_ = scroll.heightAnchor.constraint(greaterThanOrEqualToConstant: CGFloat(minH))
            floor_.priority = NSLayoutConstraint.Priority(999)
            floor_.isActive = true
        }
        return scroll
    } else if kind == "Checkbox" {
        let cb = NDCheckboxView()
        cb.applyCreate(checked: propBool(props, "checked") ?? false, label: propStr(props, "label") ?? "")
        return cb
    } else if kind == "Radio" {
        let r = NSButton(radioButtonWithTitle: propStr(props, "label") ?? "", target: nil, action: nil)
        r.state = (propBool(props, "checked") ?? false) ? .on : .off
        if let g = propStr(props, "group") {
            radioGroupIdentifier[ObjectIdentifier(r)] = g   // mutual exclusion wired in connectEvents (T4)
        } else {
            FileHandle.standardError.write("ND_WARN Radio without group prop\n".data(using: .utf8)!)
        }
        return r
    } else if kind == "Select" {
        let pop = NSPopUpButton(frame: .zero, pullsDown: false)
        if let opts = propArray(props, "options") { pop.addItems(withTitles: opts) }
        let idx = propInt(props, "selectedIndex") ?? 0
        if idx >= 0 && idx < pop.numberOfItems { pop.selectItem(at: idx) }
        return pop
    } else if kind == "Slider" {
        let min = propDouble(props, "min") ?? 0
        let max = propDouble(props, "max") ?? 100
        let value = propDouble(props, "value") ?? 0
        let step = propDouble(props, "step") ?? 1
        let snapsToStep = step > 0 && abs(step - 1) > 1e-9
        let slider = NDSliderView()
        slider.applyCreate(min: min, max: max, step: step, snapsToStep: snapsToStep, value: value, vertical: (propStr(props, "orientation") ?? "horizontal") == "vertical")
        return slider
    } else if kind == "ProgressBar" {
        return makeProgressBar(props)  // SwiftUI ProgressView hosted via NDHostedLeaf
    } else if kind == "Image" {
        let iv = NSImageView()
        // symbolScale/symbolWeight/symbolRenderingMode are create-only; the
        // configuration is captured per view so an iconName update re-resolves
        // with the same symbol treatment (Icons.swift).
        if let cfg = ndSymbolConfiguration(scale: propStr(props, "symbolScale"), weight: propStr(props, "symbolWeight"), renderingMode: propStr(props, "symbolRenderingMode")) {
            ndImageSymbolConfigs[ObjectIdentifier(iv)] = cfg
        }
        if let p = propStr(props, "path") {
            iv.image = NSImage(contentsOfFile: p)
        } else if let n = propStr(props, "iconName") {
            iv.image = ndResolveSymbolImage(n, config: ndImageSymbolConfigs[ObjectIdentifier(iv)])  // NDShell/Icons.swift (hand-written)
        }
        ndImageApplyPixelSize(iv, propInt(props, "pixelSize"))  // NDShell/Icons.swift (hand-written)
        return iv
    } else if kind == "ScrollView" {
        let sv = NSScrollView()
        sv.hasVerticalScroller = true
        if propStr(props, "hscroll") == "never" { sv.hasHorizontalScroller = false }
        sv.drawsBackground = false
        let doc = FlippedView()
        sv.documentView = doc
        doc.translatesAutoresizingMaskIntoConstraints = false
        NSLayoutConstraint.activate([
            doc.leadingAnchor.constraint(equalTo: sv.contentView.leadingAnchor),
            doc.trailingAnchor.constraint(equalTo: sv.contentView.trailingAnchor),
            doc.topAnchor.constraint(equalTo: sv.contentView.topAnchor),
            doc.widthAnchor.constraint(equalTo: sv.contentView.widthAnchor),
        ])
        let minH = propInt(props, "minContentHeight") ?? 0
        if minH > 0 {
            sv.frame.size.height = CGFloat(minH)
            let floor_ = sv.heightAnchor.constraint(greaterThanOrEqualToConstant: CGFloat(minH))
            floor_.priority = NSLayoutConstraint.Priority(999)
            floor_.isActive = true
        }
        return sv
    } else if kind == "Separator" {
        let sep = NSBox()
        sep.boxType = .separator
        let vertical = (propStr(props, "orientation") ?? "horizontal") == "vertical"
        sep.frame = vertical ? NSRect(x: 0, y: 0, width: 1, height: 24) : NSRect(x: 0, y: 0, width: 24, height: 1)
        return sep
    } else if kind == "Spinner" {
        return makeSpinner(props)  // SwiftUI ProgressView hosted via NDHostedLeaf
    } else if kind == "TabView" {
        // NSTabViewController, not a bare NSTabView: it sizes and centers the
        // segmented control, gives the segments a common minimum width, and
        // applies the standard content inset. A bare NSTabView shredded a
        // sixteen-page gallery to one character per label.
        // The ABI handle must stay an NSView, so the controller is stashed
        // against controller.view (the ndSplitControllers pattern) and the
        // apply/structural arms resolve it back with ndTabViewController(for:).
        // selectedIndex is ignored at create: pages attach afterwards (mirrors genZigCreateBody).
        // NDTabViewController, not the stock class: the subclass is what turns
        // AppKit's own didSelect delegate callback into `selectionChanged`.
        let tabController = NDTabViewController()
        tabController.tabStyle = .segmentedControlOnTop
        ndTabViewControllers[ObjectIdentifier(tabController.view)] = tabController
        return tabController.view
    } else if kind == "Grid" {
        let grid = NSGridView(numberOfColumns: 1, rows: 0)
        return grid
    } else if kind == "ListView" {
        return makeListView(props)  // NSScrollView+NSTableView, view-based recycling (M6b-D2)
    } else if kind == "WebView" {
        return NDWebView(url: propStr(props, "url"), profile: propStr(props, "profile") ?? "", contextMenuMode: propStr(props, "contextMenuMode") ?? "native")  // WKWebView subclass (M14, NDShell/NDWebView.swift)
    } else if kind == "NativeView" {
        let viewKind = propStr(props, "viewKind") ?? ""
        let propsJson = propStr(props, "props") ?? "{}"
        if let p = nd_plugin_view_create(viewKind, propsJson) {
            return unsafeBitCast(p, to: NSView.self)
        }
        return NSView()
    } else if kind == "SplitView" {
        let controller = NDSplitViewController()
        controller.splitView.isVertical = true
        controller.splitView.dividerStyle = .thin
        ndSplitControllers[ObjectIdentifier(controller.splitView)] = controller
        if let w = propDouble(props, "sidebarWidth"), w > 0 {
            splitViewSidebarFraction[ObjectIdentifier(controller.splitView)] = w
        }
        if let lw = propDouble(props, "listWidth"), lw > 0 {
            splitViewListFraction[ObjectIdentifier(controller.splitView)] = lw
        }
        if propBool(props, "collapsed") ?? false {
            splitViewCollapsed[ObjectIdentifier(controller.splitView)] = true
        }
        return controller.splitView
    } else if kind == "HeaderBar" {
        let bar = NDHeaderBarView()
        bar.ndTitle = propStr(props, "title") ?? ""
        // showTitleButtons is GTK-side chrome (per-pane window controls);
        // the traffic lights are window-level on this platform.
        bar.ndSubtitle = propStr(props, "subtitle") ?? ""
        ndHeaderBarApplyNav(bar, canGoBack: propBool(props, "canGoBack"), canGoForward: propBool(props, "canGoForward"))
        return bar
    } else if kind == "ToolbarView" {
        let pane = NDToolbarPaneView()
        let paneID = ObjectIdentifier(pane)
        ndToolbarPaneTopBarStyles[paneID] = propStr(props, "topBarStyle") ?? "flat"
        ndToolbarPaneBottomBarStyles[paneID] = propStr(props, "bottomBarStyle") ?? "flat"
        if propBool(props, "extendContentToTopEdge") ?? false {
            ndToolbarPaneExtendsToTopEdge.insert(paneID)
        }
        return pane
    } else if kind == "SearchInput" {
        let search = NDSearchField(string: propStr(props, "text") ?? "")
        if let ph = propStr(props, "placeholder") { search.placeholderString = ph }
        return search
    } else if kind == "SourceList" {
        return makeSourceList(props)  // NSScrollView+NSTableView(.sourceList) (M11 Wave 2, NDGen/SourceList.swift)
    } else if kind == "SourceTree" {
        return makeSourceTree(props)  // NSOutlineView .sourceList in NSScrollView (NDShell/SourceTrees.swift)
    } else if kind == "Menubar" {
        return ndMenubarCreate(propBool(props, "defaults") ?? true)
    } else if kind == "Menu" {
        return ndMenuCreate(propStr(props, "label") ?? "")
    } else if kind == "MenuItem" {
        return ndMenuItemCreate(props)
    } else if kind == "SettingsGroup" {
        let group = NDSettingsGroupView()
        group.ndTitle = propStr(props, "title") ?? ""
        group.ndDescription = propStr(props, "description") ?? ""
        return group
    } else if kind == "Row" {
        return makeRow(props)  // grouped form row: title/subtitle + prefix/suffix slots (NDShell/Rows.swift)
    } else if kind == "SwitchRow" {
        return makeSwitchRow(props)  // form row with a trailing NSSwitch (NDShell/Rows.swift)
    } else if kind == "Clamp" {
        return makeClamp(props)  // centered max-width content column (NDShell/Clamp.swift)
    } else if kind == "Switch" {
        let toggle = NDSwitchView()
        toggle.applyCreate(checked: propBool(props, "checked") ?? false)
        return toggle
    } else if kind == "ToggleButton" {
        let lbl = propStr(props, "label") ?? ""
        let b = NDButton(title: lbl, target: nil, action: nil)
        b.ndIsToggle = true // keeps its view in a toolbar (no promotion; state must stay visible)
        b.setButtonType(.pushOnPushOff); b.bezelStyle = .rounded
        if let icon = propStr(props, "iconName") {
            ndApplyButtonIcon(b, iconName: icon, label: lbl)  // NDShell/Icons.swift (hand-written)
        }
        b.state = (propBool(props, "active") ?? false) ? .on : .off
        return b
    } else if kind == "SegmentedControl" {
        let seg = NDSegmentedControlView()
        seg.applyCreate(options: propArray(props, "options") ?? [], selectedIndex: propInt(props, "selectedIndex") ?? 0)
        return seg
    } else if kind == "NumberInput" {
        return makeNumberInput(props)  // NSTextField+NSStepper composite (M15, NDShell/NumberInput.swift)
    } else if kind == "LinkButton" {
        return makeLinkButton(props)  // SwiftUI .buttonStyle(.link) in NSHostingView (M15, NDShell/LinkButtons.swift)
    } else if kind == "LevelIndicator" {
        let li = NSLevelIndicator()
        li.levelIndicatorStyle = ndLevelIndicatorStyle(propStr(props, "indicatorStyle") ?? "continuous", discrete: propBool(props, "discrete") ?? false)
        li.minValue = propDouble(props, "min") ?? 0
        li.maxValue = propDouble(props, "max") ?? 1
        li.warningValue = propDouble(props, "warningValue") ?? (li.maxValue + 1)
        li.criticalValue = propDouble(props, "criticalValue") ?? (li.maxValue + 1)
        li.doubleValue = propDouble(props, "value") ?? 0
        return li
    } else if kind == "ColorPicker" {
        return makeColorPicker(props)  // NSColorWell .minimal (M15, NDShell/ColorWells.swift)
    } else if kind == "Banner" {
        return makeBanner(props)  // SwiftUI chrome in NSHostingView (M15, NDShell/Banners.swift)
    } else if kind == "MenuButton" {
        return makeMenuButton(props)  // NSComboButton .unified (M15, NDShell/ComboButtons.swift)
    } else if kind == "SplitButton" {
        return makeSplitButton(props)  // NSComboButton .split (M15, NDShell/ComboButtons.swift)
    } else if kind == "Popover" {
        return makePopover(props)  // host-only handle owning a lazy .transient NSPopover (M15, NDShell/Popovers.swift)
    } else if kind == "Expander" {
        return makeExpander(props)  // .pushDisclosure + collapsible section (M15, NDShell/Expanders.swift)
    } else if kind == "StatusPage" {
        return makeStatusPage(props)  // SwiftUI ContentUnavailableView + actions row (M15, NDShell/StatusPages.swift)
    } else if kind == "ToastOverlay" {
        return makeToastOverlay(props)  // child-window toast presenter (M15, NDShell/Toasts.swift)
    } else if kind == "DatePicker" {
        return makeDatePicker(props)  // NSDatePicker .yearMonthDay, pinned UTC (M15, NDShell/DatePickers.swift)
    } else if kind == "Table" {
        return makeTable(props)  // view-based NSTableView in NSScrollView (M15, NDShell/Tables.swift)
    } else if kind == "TreeView" {
        return makeTreeView(props)  // NSOutlineView in NSScrollView (M15, NDShell/TreeViews.swift)
    } else if kind == "FontPicker" {
        return makeFontPicker(props)  // shared NSFontPanel + coordinator (M15, NDShell/FontPickers.swift)
    } else if kind == "Video" {
        return makeVideoView(props)  // AVKit AVPlayerView (M15, NDShell/Videos.swift)
    } else if kind == "TrayItem" {
        return makeTrayItem(props)  // NSStatusItem behind a host-only handle (M15, NDShell/TrayItems.swift)
    } else if kind == "ShareButton" {
        return makeShareButton(props)  // NSSharingServicePicker anchor button (M15, NDShell/ShareButtons.swift)
    } else if kind == "Terminal" {
        let cols = propInt(props, "cols") ?? 80
        let rows = propInt(props, "rows") ?? 24
        let fontSize = propInt(props, "fontSize") ?? 13
        let fontFamily = propStr(props, "fontFamily")
        let palette = propStr(props, "palette")
        let foreground = propStr(props, "foreground") ?? ""
        let background = propStr(props, "background") ?? ""
        // SEAM: NDTerminalView init signatures are the published contract with NDTerminalView.swift (package nd-terminal-surfaces) — keep both sides byte-for-byte in sync.
        //   init(command: String?, cwd: String?, fontSize: Int, fontFamily: String?, palette: String?, foreground: String, background: String, cols: Int, rows: Int)
        //   init(remote: Bool, host: String?, port: Int, sessionId: String?, ticket: String?, restoreScrollback: Bool, fontSize: Int, fontFamily: String?, palette: String?, foreground: String, background: String, cols: Int, rows: Int)
        if propBool(props, "remote") ?? false {
            return NDTerminalView(remote: true, host: propStr(props, "host"), port: propInt(props, "port") ?? 4618, sessionId: propStr(props, "sessionId"), ticket: propStr(props, "ticket"), restoreScrollback: propBool(props, "restoreScrollback") ?? false, fontSize: fontSize, fontFamily: fontFamily, palette: palette, foreground: foreground, background: background, cols: cols, rows: rows)
        }
        return NDTerminalView(command: propStr(props, "command"), cwd: propStr(props, "cwd"), fontSize: fontSize, fontFamily: fontFamily, palette: palette, foreground: foreground, background: background, cols: cols, rows: rows)
    } else if kind == "Paned" {
        let horizontal = (propStr(props, "orientation") ?? "horizontal") != "vertical"
        let split = NSSplitView()
        split.isVertical = horizontal
        // The .thick default paints the divider in the window background,
        // which reads as no divider at all between two content panes. .thin
        // is the 1pt separatorColor hairline Xcode and Mail use.
        split.dividerStyle = .thin
        let controller = PanedController(split: split)
        ndPanedControllers[ObjectIdentifier(split)] = controller
        controller.setPositionFraction(propDouble(props, "position") ?? 0.5)
        return split
    } else if kind == "CommandPalette" {
        return makeCommandPalette(props)  // host-only handle: dimmed scrim + centered card over the window (NDShell/CommandPalette.swift)
    } else if kind == "Avatar" {
        let av = NDAvatarView()
        av.applyCreate(size: propInt(props, "size") ?? 32, text: propStr(props, "text") ?? "", showInitials: propBool(props, "showInitials") ?? true)
        return av
    } else if kind == "Badge" {
        let badge = NDBadgeView()
        badge.applyCreate(dot: propBool(props, "dot") ?? false, label: propStr(props, "label") ?? "", variant: propStr(props, "variant") ?? "neutral")
        return badge
    } else if kind == "Tag" {
        let tag = NDTagView()
        tag.applyCreate(label: propStr(props, "label") ?? "", variant: propStr(props, "variant") ?? "neutral", removable: propBool(props, "removable") ?? false)
        return tag
    } else if kind == "Kbd" {
        let kbd = NDKbdView()
        kbd.setKeys(propStr(props, "keys") ?? "")
        return kbd
    } else if kind == "ComboBox" {
        return ndMakeComboBox(props)  // NSComboBox, its own delegate
    } else if kind == "Breadcrumb" {
        return ndMakeBreadcrumb(props)  // NSPathControl driven by explicit path items
    } else if kind == "Dialog" {
        return ndMakeDialog(props)  // host-only handle owning an NSWindow run as a sheet on the tree parent's window
    } else if kind == "Sheet" {
        return ndMakeSheet(props)  // host-only handle; content is presented as a real sheet
    } else if kind == "RichText" {
        return ndMakeRichText(props)  // non-editable NSTextView in an NSScrollView, fed an NSAttributedString
    } else if kind == "ProgressCircle" {
        return makeProgressCircle(props)  // SwiftUI Gauge(.accessoryCircularCapacity) hosted via NDHostedLeaf
    } else if kind == "Skeleton" {
        return ndMakeSkeleton(props)  // CAGradientLayer shimmer, static under reduce-motion
    } else if kind == "Chart" {
        return makeChart(props, minContentHeight: propInt(props, "minContentHeight") ?? 160)  // SwiftUI Swift Charts in an NSHostingView (NDShell/Charts.swift)
    } else if kind == "CodeEditor" {
        return ndCodeEditorCreate(props)  // TextKit 2 NSTextView in a ruler'd scroll view (NDShell/CodeEditors.swift)
    }
    FileHandle.standardError.write("ND_WARN unknown widget kind=\(kind)\n".data(using: .utf8)!)
    return nil
}

@MainActor func ndApplyProps(_ view: NSView, _ kind: String, _ propsJson: String) {
    let props = parseProps(propsJson)
    // `tooltip`/`enabled` have no universal NSView peer — ndApplyTooltip/
    // ndApplyEnabled route each to NSView, NSControl or a hosted leaf's
    // SwiftUI state as appropriate (below).
    if let tip = propStr(props, "tooltip") { ndApplyTooltip(view, tip) }
    if let on = propBool(props, "enabled") { ndApplyEnabled(view, on) }
    ndDragDropApply(view, props)
    if kind == "Window" {
        if let t = propStr(props, "title"), let win = ndWindow(for: view) { win.title = t }
    } else if kind == "Box" {
        if let sp = propInt(props, "spacing"), let stack = view as? NSStackView {
            // -1 sentinel = platform standard, same as the create arm.
            stack.spacing = sp < 0 ? ndStandardSpacing : CGFloat(sp)
        }
    } else if kind == "Button" {
        if let l = propStr(props, "label"), let b = view as? NSButton {
            b.title = l
            // ndApplyButtonIcon picked imageOnly/imageLeading from the
            // create-time label; a button that gains or loses one follows.
            if b.image != nil { b.imagePosition = l.isEmpty ? .imageOnly : .imageLeading }
        }
        if let icon = propStr(props, "iconName"), let btn = view as? NSButton { ndButtonApplyIconName(btn, icon) }
        if let data = propStr(props, "iconData"), let btn = view as? NSButton { ndApplyButtonIconData(btn, iconData: data, label: btn.title) }
        if let pr = propBool(props, "prominent"), let btn = view as? NSButton { ndButtonApplyProminent(btn, pr) }
        if let bd = propStr(props, "badge"), let btn = view as? NSButton { ndButtonApplyBadge(btn, bd) }
        if let sz = propStr(props, "size"), let btn = view as? NSButton { ndButtonApplySize(btn, sz) }
    } else if kind == "TextInput" {
        if let t = propStr(props, "text"), let field = view as? NSTextField, field.stringValue != t {
            withEchoSuppressed(view) { field.stringValue = t }
        }
        if let ph = propStr(props, "placeholder"), let field = view as? NSTextField {
            field.placeholderString = ph
        }
        if let e = propBool(props, "editable"), let field = view as? NSTextField {
            field.isEditable = e
        }
    } else if kind == "TextArea" {
        if let t = propStr(props, "text"), let scroll = view as? NSScrollView,
           let textView = scroll.documentView as? NSTextView, textView.string != t {
            withEchoSuppressed(view) { textView.string = t }
        }
    } else if kind == "Checkbox" {
        if let c = propBool(props, "checked") { (view as? NDCheckboxView)?.setCheckedFromProps(c) }
        if let l = propStr(props, "label") { (view as? NDCheckboxView)?.setLabel(l) }
    } else if kind == "Radio" {
        if let c = propBool(props, "checked"), let btn = view as? NSButton {
            let want: NSControl.StateValue = c ? .on : .off
            if btn.state != want {
                withEchoSuppressed(view) { btn.state = want }
            }
        }
        if let l = propStr(props, "label"), let btn = view as? NSButton {
            btn.title = l
        }
    } else if kind == "Select" {
        if let idx = propInt(props, "selectedIndex"), let pop = view as? NSPopUpButton, pop.indexOfSelectedItem != idx {
            withEchoSuppressed(view) { pop.selectItem(at: idx) }
        }
    } else if kind == "Slider" {
        if let v = propDouble(props, "value") { (view as? NDSliderView)?.setValueFromProps(v) }
    } else if kind == "ProgressBar" {
        ndProgressBarApply(view, props)
    } else if kind == "Image" {
        if let p_ = propStr(props, "path"), let iv = view as? NSImageView {
            iv.image = NSImage(contentsOfFile: p_)
        }
        if let n = propStr(props, "iconName"), let iv = view as? NSImageView {
            iv.image = ndResolveSymbolImage(n, config: ndImageSymbolConfigs[ObjectIdentifier(iv)])  // NDShell/Icons.swift (hand-written)
        }
        if let iv = view as? NSImageView {
            ndImageApplyPixelSize(iv, propInt(props, "pixelSize"))  // NDShell/Icons.swift (hand-written)
        }
    } else if kind == "Spinner" {
        ndSpinnerApply(view, props)
    } else if kind == "TabView" {
        if let idx = propInt(props, "selectedIndex"), let tabs = ndTabViewController(for: view),
           idx >= 0 && idx < tabs.tabViewItems.count, tabs.selectedTabViewItemIndex != idx {
            // A React-driven page change must not echo back as selectionChanged.
            withEchoSuppressed(view) { tabs.selectedTabViewItemIndex = idx }
        }
    } else if kind == "ListView" {
        if let items = propArray(props, "items") {
            ndListViewSetItems(view, items)  // NDGen/ListView.swift (T3, hand-written)
        }
        if let idx = propInt(props, "selectedIndex") {
            ndListViewSetSelectedIndex(view, idx)  // NDGen/ListView.swift (T3, hand-written)
        }
        ndEmptyStateApply(view, props)  // emptyIconName/emptyTitle/emptyDescription merged (NDShell/EmptyState.swift)
        // "emptyTitle" handled by ndEmptyStateApply above (merged).
        // "emptyDescription" handled by ndEmptyStateApply above (merged).
    } else if kind == "WebView" {
        if let u = propStr(props, "url"), let wv = view as? NDWebView { wv.ndSetURL(u) }
        if let m = propStr(props, "contextMenuMode"), let wv = view as? NDWebView { wv.ndSetContextMenuMode(m) }
    } else if kind == "NativeView" {
        if let pj = propStr(props, "props"), let vk = propStr(props, "viewKind") {
            nd_plugin_view_apply_props(vk, Unmanaged.passUnretained(view).toOpaque(), pj)
        }
    } else if kind == "SplitView" {
        if let c = propBool(props, "collapsed"), let split = view as? NSSplitView,
           let controller = ndSplitViewController(for: split) {
            splitViewCollapsed[ObjectIdentifier(split)] = c
            if let sidebarItem = controller.splitViewItems.first(where: { $0.behavior == .sidebar }) {
                sidebarItem.isCollapsed = c
            }
        }
    } else if kind == "HeaderBar" {
        if let t = propStr(props, "title"), let bar = view as? NDHeaderBarView {
            bar.ndTitle = t
            if !t.isEmpty { bar.titleField.stringValue = t }
            // defaultItemIdentifiers gates the title item on a non-empty
            // ndTitle, so a title appearing or disappearing changes the set.
            (bar.pane?.manager ?? ndWindowToolbarManager)?.scheduleRebuild()
        }
        if let s = propStr(props, "subtitle"), let bar = view as? NDHeaderBarView { ndHeaderBarApplySubtitle(bar, s) }
        if let bar = view as? NDHeaderBarView {
            ndHeaderBarApplyNav(bar, canGoBack: propBool(props, "canGoBack"), canGoForward: propBool(props, "canGoForward"))
        }
    } else if kind == "SearchInput" {
        if let t = propStr(props, "text"), let field = view as? NSTextField, field.stringValue != t {
            withEchoSuppressed(view) { field.stringValue = t }
        }
        if let ph = propStr(props, "placeholder"), let field = view as? NSTextField {
            field.placeholderString = ph
        }
    } else if kind == "SourceList" {
        if let raw = propObjArray(props, "items") {
            ndSourceListSetItems(view, raw)  // NDGen/SourceList.swift (M11 Wave 2, hand-written)
        }
        if let idx = propInt(props, "selectedIndex") {
            ndSourceListSetSelectedIndex(view, idx)  // NDGen/SourceList.swift (M11 Wave 2, hand-written)
        }
        ndEmptyStateApply(view, props)  // emptyIconName/emptyTitle/emptyDescription merged (NDShell/EmptyState.swift)
        // "emptyTitle" handled by ndEmptyStateApply above (merged).
        // "emptyDescription" handled by ndEmptyStateApply above (merged).
    } else if kind == "SourceTree" {
        if let nodes = propObjArray(props, "nodes") { ndSourceTreeSetNodes(view, nodes) }
        if let actions = propObjArray(props, "actions") { ndSourceTreeSetActions(view, actions) }
        if let sel = propStr(props, "selectedId") { ndSourceTreeSetSelectedId(view, sel) }
        ndEmptyStateApply(view, props)  // emptyIconName/emptyTitle/emptyDescription merged (NDShell/EmptyState.swift)
        // "emptyTitle" handled by ndEmptyStateApply above (merged).
        // "emptyDescription" handled by ndEmptyStateApply above (merged).
    } else if kind == "Menu" {
        if let l = propStr(props, "label"), let node = ndMenuNode(view) {
            node.label = l
            ndMenuManager?.scheduleRebuild()  // the label is baked into NSMenu at build time
        }
    } else if kind == "MenuItem" {
        if let l = propStr(props, "label"), let node = ndMenuNode(view) {
            node.label = l
            ndMenuManager?.scheduleRebuild()  // the label is baked into NSMenu at build time
        }
        if let en = propBool(props, "enabled") { ndMenuItemSetEnabled(view, en) }
    } else if kind == "SettingsGroup" {
        ndSettingsGroupApply(view, props)  // title/description merged
        // "description" handled by ndSettingsGroupApply above (merged).
    } else if kind == "Row" {
        ndRowApply(view, props)  // title/subtitle/iconData merged
        // "subtitle" handled by ndRowApply above (merged).
        // "iconData" handled by ndRowApply above (merged).
    } else if kind == "SwitchRow" {
        ndSwitchRowApply(view, props)  // title/subtitle/checked merged (checked is echo-suppressed inside)
        // "subtitle" handled by ndSwitchRowApply above (merged).
        // "checked" handled by ndSwitchRowApply above (merged).
    } else if kind == "Switch" {
        if let c = propBool(props, "checked") { (view as? NDSwitchView)?.setCheckedFromProps(c) }
    } else if kind == "ToggleButton" {
        if let l = propStr(props, "label"), let btn = view as? NSButton {
            btn.title = l
        }
        if let a = propBool(props, "active"), let btn = view as? NSButton {
            let want: NSControl.StateValue = a ? .on : .off
            if btn.state != want {
                withEchoSuppressed(view) { btn.state = want }
            }
        }
    } else if kind == "SegmentedControl" {
        if let idx = propInt(props, "selectedIndex") { (view as? NDSegmentedControlView)?.setSelectedIndexFromProps(idx) }
    } else if kind == "NumberInput" {
        if let v = propDouble(props, "value") {
            withEchoSuppressed(view) { ndNumberInputSetValue(view, v) }
        }
    } else if kind == "LinkButton" {
        ndLinkButtonApply(view, props)
        // "uri" handled by ndLinkButtonApply above (merged).
        // "visited" handled by ndLinkButtonApply above (merged).
        // "openExternal" handled by ndLinkButtonApply above (merged).
    } else if kind == "LevelIndicator" {
        if let v = propDouble(props, "value"), let li = view as? NSLevelIndicator { li.doubleValue = v }
        if let wv = propDouble(props, "warningValue"), let li = view as? NSLevelIndicator { li.warningValue = wv }
        if let cv = propDouble(props, "criticalValue"), let li = view as? NSLevelIndicator { li.criticalValue = cv }
    } else if kind == "ColorPicker" {
        if let v = propStr(props, "value") { ndColorPickerSetValue(view, v) }
    } else if kind == "Banner" {
        ndBannerApply(view, props)  // title/buttonLabel/revealed merged
        // "buttonLabel" handled by ndBannerApply above (merged).
        // "revealed" handled by ndBannerApply above (merged).
    } else if kind == "MenuButton" {
        if let l = propStr(props, "label"), let combo = view as? NSComboButton { combo.title = l }
        if let ic = propStr(props, "iconName"), let combo = view as? NSComboButton { ndApplyComboIcon(combo, ic) }
    } else if kind == "SplitButton" {
        if let l = propStr(props, "label"), let combo = view as? NSComboButton { combo.title = l }
        if let ic = propStr(props, "iconName"), let combo = view as? NSComboButton { ndApplyComboIcon(combo, ic) }
    } else if kind == "Popover" {
        if let o = propBool(props, "open") { ndPopoverApplyOpen(view, o) }
        if let pos = propStr(props, "position") { ndPopoverApplyPosition(view, pos) }
    } else if kind == "Expander" {
        ndExpanderApply(view, props)  // label/expanded merged (expanded is echo-suppressed inside)
        // "expanded" handled by ndExpanderApply above (merged).
    } else if kind == "StatusPage" {
        ndStatusPageApply(view, props)  // iconName/title/description merged
        // "title" handled by ndStatusPageApply above (merged).
        // "description" handled by ndStatusPageApply above (merged).
    } else if kind == "DatePicker" {
        if let v = propStr(props, "value") { ndDatePickerSetValue(view, v) }
        // min/max merge in one call (absent keys keep prior state).
        ndDatePickerSetLimits(view, propStr(props, "minDate"), propStr(props, "maxDate"))
        // handled together with minDate above (ndDatePickerSetLimits merges both).
    } else if kind == "Table" {
        if let cols = propObjArray(props, "columns") { ndTableSetColumns(view, cols) }
        if let rows = propObjArray(props, "rows") { ndTableSetRows(view, rows) }
        if let idx = propInt(props, "selectedIndex") { ndTableSetSelectedIndex(view, idx) }
        if let rows = propIntArray(props, "selectedIndexes") { ndTableSetSelectedIndexes(view, rows) }
        if let on = propBool(props, "columnsReorderable") { ndTableSetColumnsReorderable(view, on) }
        if let sep = propBool(props, "showRowSeparators") { ndTableSetShowRowSeparators(view, sep) }
        ndEmptyStateApply(view, props)  // emptyIconName/emptyTitle/emptyDescription merged (NDShell/EmptyState.swift)
        // "emptyTitle" handled by ndEmptyStateApply above (merged).
        // "emptyDescription" handled by ndEmptyStateApply above (merged).
    } else if kind == "TreeView" {
        if let nodes = propObjArray(props, "nodes") { ndTreeViewSetNodes(view, nodes) }
        if let idx = propInt(props, "selectedIndex") { ndTreeViewSetSelectedIndex(view, idx) }
        ndEmptyStateApply(view, props)  // emptyIconName/emptyTitle/emptyDescription merged (NDShell/EmptyState.swift)
        // "emptyTitle" handled by ndEmptyStateApply above (merged).
        // "emptyDescription" handled by ndEmptyStateApply above (merged).
    } else if kind == "FontPicker" {
        if let v = propStr(props, "value") { ndFontPickerSetValue(view, v) }
    } else if kind == "Video" {
        if let s = propStr(props, "src") { ndVideoSetSrc(view, s) }
        if let l = propBool(props, "loop") { ndVideoSetLoop(view, l) }
    } else if kind == "TrayItem" {
        ndTrayItemApply(view, props)  // iconName/tooltip merged
        // "tooltip" handled by ndTrayItemApply above (merged).
    } else if kind == "ShareButton" {
        ndShareButtonApply(view, props)  // label/items merged
        // "items" handled by ndShareButtonApply above (merged).
    } else if kind == "Paned" {
        if let f = propDouble(props, "position"), let split = view as? NSSplitView,
           let controller = ndPanedController(for: split) {
            controller.setPositionFraction(f)
        }
    } else if kind == "CommandPalette" {
        if let o = propBool(props, "open") { ndCommandPaletteApplyOpen(view, o) }
        if let ph = propStr(props, "placeholder") { ndCommandPaletteApplyPlaceholder(view, ph) }
        if let q = propStr(props, "query") { ndCommandPaletteApplyQuery(view, q) }
        if let raw = propObjArray(props, "items") { ndCommandPaletteApplyItems(view, raw) }
    } else if kind == "Avatar" {
        if let t = propStr(props, "text"), let av = view as? NDAvatarView { av.setText(t) }
        if let ip = propStr(props, "imagePath"), let av = view as? NDAvatarView { av.setImagePath(ip) }
    } else if kind == "Badge" {
        if let l = propStr(props, "label") { (view as? NDBadgeView)?.setLabel(l) }
        if let v = propStr(props, "variant") { (view as? NDBadgeView)?.setVariant(v) }
    } else if kind == "Tag" {
        if let l = propStr(props, "label") { (view as? NDTagView)?.setLabel(l) }
        if let v = propStr(props, "variant") { (view as? NDTagView)?.setVariant(v) }
    } else if kind == "Kbd" {
        if let k = propStr(props, "keys") { (view as? NDKbdView)?.setKeys(k) }
    } else if kind == "ComboBox" {
        if let idx = propInt(props, "selectedIndex"), let combo = view as? NSComboBox,
           idx >= 0, idx < combo.numberOfItems, combo.indexOfSelectedItem != idx {
            withEchoSuppressed(view) { combo.selectItem(at: idx) }
        }
        if let t = propStr(props, "text"), let combo = view as? NSComboBox, combo.stringValue != t {
            withEchoSuppressed(view) { combo.stringValue = t }
        }
    } else if kind == "Breadcrumb" {
        if let items = propArray(props, "items"), let path = view as? NDPathControl {
            path.titles = items
            path.rebuild()
        }
        if let idx = propInt(props, "selectedIndex"), let path = view as? NDPathControl {
            path.selectedCrumb = idx
            path.rebuild()
        }
    } else if kind == "Dialog" {
        if let o = propBool(props, "open") {
            // Both handles track presented/pending themselves, so a re-render
            // carrying an unchanged `open` costs nothing.
            (view as? NDDialogHandleView)?.applyOpen(o)
            (view as? NDSheetHandleView)?.applyOpen(o)
        }
        if let t = propStr(props, "title") { (view as? NDDialogHandleView)?.title = t }
        // Read at present time; an update to a sheet already up keeps its size.
        if let v = propInt(props, "contentWidth") { (view as? NDDialogHandleView)?.contentWidth = v }
        if let v = propInt(props, "contentHeight") { (view as? NDDialogHandleView)?.contentHeight = v }
        if let c = propBool(props, "closable") { (view as? NDDialogHandleView)?.closable = c }
    } else if kind == "Sheet" {
        if let o = propBool(props, "open") {
            // Both handles track presented/pending themselves, so a re-render
            // carrying an unchanged `open` costs nothing.
            (view as? NDDialogHandleView)?.applyOpen(o)
            (view as? NDSheetHandleView)?.applyOpen(o)
        }
        if let e = propStr(props, "edge") { (view as? NDSheetHandleView)?.edge = e }
        // Read at present time; an update to a sheet already up keeps its size.
        if let s = propInt(props, "size") { (view as? NDSheetHandleView)?.size = s }
    } else if kind == "RichText" {
        if let md = propStr(props, "markdown") { ndRichTextSetMarkdown(view, md) }
        if let s = propBool(props, "selectable") { ndRichTextSetSelectable(view, s) }
    } else if kind == "ProgressCircle" {
        ndProgressCircleApply(view, props)  // fraction/lineWidth/showLabel merged into one refresh
        // "lineWidth" handled by ndProgressCircleApply above (merged).
        // "showLabel" handled by ndProgressCircleApply above (merged).
    } else if kind == "Skeleton" {
        if let wd = propInt(props, "width") { (view as? NDSkeletonView)?.contentWidth = wd }
        if let h = propInt(props, "height") { (view as? NDSkeletonView)?.contentHeight = h }
        if let r = propInt(props, "radius") { (view as? NDSkeletonView)?.radius = r }
        if let a = propBool(props, "animated") { (view as? NDSkeletonView)?.animated = a }
    } else if kind == "Chart" {
        ndChartApply(view, props)  // one rebuild of the SwiftUI Chart body covers every key
        // "series" handled by ndChartApply above (merged).
        // "xLabel" handled by ndChartApply above (merged).
        // "yLabel" handled by ndChartApply above (merged).
        // "showLegend" handled by ndChartApply above (merged).
        // "showGrid" handled by ndChartApply above (merged).
        // "animated" handled by ndChartApply above (merged).
    } else if kind == "CodeEditor" {
        ndCodeEditorApply(view, props)  // text/language/theme/diagnostics all re-attribute one text storage
        // "language" handled by ndCodeEditorApply above (merged).
        // "theme" handled by ndCodeEditorApply above (merged).
        // "showLineNumbers" handled by ndCodeEditorApply above (merged).
        // "readOnly" handled by ndCodeEditorApply above (merged).
        // "tabWidth" handled by ndCodeEditorApply above (merged).
        // "diagnostics" handled by ndCodeEditorApply above (merged).
    }
}

func ndConnectEvents(_ view: NSView, _ kind: String, _ nodeID: UInt32) {
    // Drag and drop is universal (see UNIVERSAL_EVENTS in
    // tools/codegen.ts): the drag recognizer and drop zone were
    // installed by the props arm, which runs before this and so has
    // no node id yet. This is where they learn it.
    ndDragDropConnect(view, nodeID: nodeID)
    if kind == "Window" {
        ndWindowDialogsConnect(view, nodeID: nodeID)
        ndWindowTabsConnect(view, nodeID: nodeID)
    } else if kind == "Box" {
        ndHoverConnect(view, nodeID: nodeID)
    } else if kind == "Button" {
        EventDispatcher.shared.wire(view, nodeID: nodeID, name: "clicked", payload: .none, action: #selector(EventDispatcher.fireNone(_:)))
        ndHoverConnect(view, nodeID: nodeID)
    } else if kind == "TextInput" {
        EventDispatcher.shared.wire(view, nodeID: nodeID, name: "changed", payload: .text, action: #selector(EventDispatcher.fireText(_:)))
        EventDispatcher.shared.wire(view, nodeID: nodeID, name: "activate", payload: .text, action: #selector(EventDispatcher.fireText(_:)))
    } else if kind == "TextArea" {
        EventDispatcher.shared.wire(view, nodeID: nodeID, name: "changed", payload: .text, action: #selector(EventDispatcher.fireText(_:)))
    } else if kind == "Checkbox" {
        ndCheckboxConnect(view, nodeID: nodeID)
    } else if kind == "Radio" {
        EventDispatcher.shared.wire(view, nodeID: nodeID, name: "toggled", payload: .checked, action: #selector(EventDispatcher.fireChecked(_:)))
    } else if kind == "Select" {
        EventDispatcher.shared.wire(view, nodeID: nodeID, name: "selectionChanged", payload: .index, action: #selector(EventDispatcher.fireIndex(_:)))
    } else if kind == "Slider" {
        ndSliderConnect(view, nodeID: nodeID)
    } else if kind == "TabView" {
        ndTabViewConnect(view, nodeID: nodeID)
    } else if kind == "ListView" {
        EventDispatcher.shared.wire(view, nodeID: nodeID, name: "rowActivated", payload: .index, action: #selector(EventDispatcher.fireIndex(_:)))
    } else if kind == "WebView" {
        ndWebViewConnect(view, nodeID: nodeID)
    } else if kind == "NativeView" {
    } else if kind == "HeaderBar" {
        ndHeaderBarConnectNav(view, nodeID: nodeID)
    } else if kind == "SearchInput" {
        EventDispatcher.shared.wire(view, nodeID: nodeID, name: "changed", payload: .text, action: #selector(EventDispatcher.fireText(_:)))
        EventDispatcher.shared.wire(view, nodeID: nodeID, name: "activate", payload: .text, action: #selector(EventDispatcher.fireText(_:)))
    } else if kind == "SourceList" {
        EventDispatcher.shared.wire(view, nodeID: nodeID, name: "selectionChanged", payload: .index, action: #selector(EventDispatcher.fireIndex(_:)))
        EventDispatcher.shared.wire(view, nodeID: nodeID, name: "rowActivated", payload: .index, action: #selector(EventDispatcher.fireIndex(_:)))
    } else if kind == "SourceTree" {
        ndSourceTreeConnect(view, nodeID: nodeID)
    } else if kind == "MenuItem" {
        ndMenuItemConnect(view, nodeID: nodeID) // M13: NSMenuItem target/action, not EventDispatcher
    } else if kind == "Row" {
        ndRowConnect(view, nodeID: nodeID)
    } else if kind == "SwitchRow" {
        ndSwitchRowConnect(view, nodeID: nodeID)
    } else if kind == "Switch" {
        ndSwitchConnect(view, nodeID: nodeID)
    } else if kind == "ToggleButton" {
        EventDispatcher.shared.wire(view, nodeID: nodeID, name: "toggled", payload: .checked, action: #selector(EventDispatcher.fireChecked(_:)))
    } else if kind == "SegmentedControl" {
        ndSegmentedControlConnect(view, nodeID: nodeID)
    } else if kind == "NumberInput" {
        ndNumberInputConnect(view, nodeID: nodeID)
    } else if kind == "LinkButton" {
        ndLinkButtonConnect(view, nodeID: nodeID)
    } else if kind == "ColorPicker" {
        ndColorPickerConnect(view, nodeID: nodeID)
    } else if kind == "Banner" {
        ndBannerConnect(view, nodeID: nodeID)
    } else if kind == "SplitButton" {
        EventDispatcher.shared.wire(view, nodeID: nodeID, name: "clicked", payload: .none, action: #selector(EventDispatcher.fireNone(_:)))
    } else if kind == "Popover" {
        ndPopoverConnect(view, nodeID: nodeID)
    } else if kind == "Expander" {
        ndExpanderConnect(view, nodeID: nodeID)
    } else if kind == "ToastOverlay" {
        ndToastOverlayConnect(view, nodeID: nodeID)
    } else if kind == "DatePicker" {
        ndDatePickerConnect(view, nodeID: nodeID)
    } else if kind == "Table" {
        ndTableConnect(view, nodeID: nodeID)
    } else if kind == "TreeView" {
        ndTreeViewConnect(view, nodeID: nodeID)
    } else if kind == "FontPicker" {
        ndFontPickerConnect(view, nodeID: nodeID)
    } else if kind == "Terminal" {
        ndTerminalConnect(view, nodeID: nodeID)
    } else if kind == "Paned" {
        ndPanedConnect(view, nodeID: nodeID)
    } else if kind == "CommandPalette" {
        ndCommandPaletteConnect(view, nodeID: nodeID)
    } else if kind == "Tag" {
        ndTagConnect(view, nodeID: nodeID)
    } else if kind == "ComboBox" {
        ndComboBoxConnect(view, nodeID: nodeID)
    } else if kind == "Breadcrumb" {
        ndBreadcrumbConnect(view, nodeID: nodeID)
    } else if kind == "Dialog" {
        ndOverlayConnect(view, nodeID: nodeID)
    } else if kind == "Sheet" {
        ndOverlayConnect(view, nodeID: nodeID)
    } else if kind == "RichText" {
        ndRichTextConnect(view, nodeID: nodeID)
    } else if kind == "Chart" {
        ndChartConnect(view, nodeID: nodeID)
    } else if kind == "CodeEditor" {
        ndCodeEditorConnect(view, nodeID: nodeID)
    }
}

/// App -> widget imperative commands (widgetCommand NDP frame, M14).
@MainActor func ndWidgetCommand(_ view: NSView, _ kind: String, _ command: String, _ argJson: String) {
    // `focus` is first-responder status on the view's window, so one arm
    // serves every kind that declares it (see UNIVERSAL_COMMANDS in
    // tools/codegen.ts).
    if command == "focus" && kind != "Terminal" { return ndFocusView(view) }
    if kind == "Window" {
        if command == "showTabOverview" || command == "present" { ndWindowTabsCommand(view, command, argJson); return }
        ndWindowCommand(view, command, argJson)
    } else if kind == "WebView" {
        ndWebViewCommand(view, command, argJson)
    } else if kind == "ToastOverlay" {
        ndToastOverlayCommand(view, command, argJson)
    } else if kind == "Terminal" {
        ndTerminalCommand(view, command, argJson)
    } else {
        FileHandle.standardError.write("ND_WARN widgetCommand on kind=\(kind) with no commands\n".data(using: .utf8)!)
    }
}

func ndAppendChild(_ parent: NSView, _ parentKind: String, _ child: NSView, _ attachedJson: String) {
    // Cross-cutting (M15): a Popover child anchors on its tree parent
    // (never box-packed); a TrayItem is menu-bar chrome, never content;
    // a Dialog/Sheet handle records the parent it presents against.
    if ndPopoverStructuralAttach(child, parent) { return }
    if ndTrayItemStructuralAttach(child) { return }
    if ndOverlayStructuralAttach(child, parent) { return }
    let attached = parseProps(attachedJson)
    let attachedTabLabel = propStr(attached, "tabLabel") ?? ""
    let attachedTabIcon = propStr(attached, "tabIcon") ?? ""
    let attachedGridRow = propInt(attached, "gridRow") ?? 0
    let attachedGridColumn = propInt(attached, "gridColumn") ?? 0
    let attachedGridRowSpan = propInt(attached, "gridRowSpan") ?? 1
    let attachedGridColumnSpan = propInt(attached, "gridColumnSpan") ?? 1
    let attachedSlot = propStr(attached, "slot") ?? "content"
    if parentKind == "Window" {
        if ndMenuAttachToWindow(child) { return } // M13: a <menubar> child is app chrome (NSApp.mainMenu), not window content
        let window = parent.window ?? gWindow
        parent.subviews.forEach { $0.removeFromSuperview() }
        if let pane = child as? NDToolbarPaneView {
            if let win = window, win.contentViewController != nil {
                win.contentViewController = nil
                win.contentView = parent
            }
            ndToolbarPaneAttachedToWindow(pane)
            let content = pane.contentView ?? pane
            content.translatesAutoresizingMaskIntoConstraints = false
            if ndToolbarPaneExtendsToTopEdge.contains(ObjectIdentifier(pane)) {
                parent.addSubview(content)
                NSLayoutConstraint.activate([
                    content.topAnchor.constraint(equalTo: parent.topAnchor),
                    content.leadingAnchor.constraint(equalTo: parent.leadingAnchor),
                    content.trailingAnchor.constraint(equalTo: parent.trailingAnchor),
                    content.bottomAnchor.constraint(equalTo: parent.bottomAnchor),
                ])
                return
            }
            parent.addSubview(content)
            NSLayoutConstraint.activate([
                content.topAnchor.constraint(equalTo: parent.safeAreaLayoutGuide.topAnchor),
                content.leadingAnchor.constraint(equalTo: parent.leadingAnchor),
                content.trailingAnchor.constraint(equalTo: parent.trailingAnchor),
                content.bottomAnchor.constraint(equalTo: parent.bottomAnchor),
            ])
            return
        }
        if let split = child as? NSSplitView, let controller = ndSplitViewController(for: split), let win = window {
            ndInstallSplitAsWindowContent(split, controller, win)
        } else if let overlay = child as? NDToastOverlayView, let split = overlay.ndEmbeddedSplit,
                  let controller = ndSplitViewController(for: split), let win = window {
            ndInstallSplitAsWindowContent(split, controller, win)
            overlay.ndHostWindow = win
        } else {
            if let win = window, win.contentViewController != nil {
                win.contentViewController = nil
                win.contentView = parent
            }
            parent.addSubview(child)
            child.translatesAutoresizingMaskIntoConstraints = false
            let inset = ndWindowRootInset(child)
            let guide = parent.safeAreaLayoutGuide
            NSLayoutConstraint.activate([
                child.topAnchor.constraint(equalTo: guide.topAnchor, constant: inset),
                child.leadingAnchor.constraint(equalTo: guide.leadingAnchor, constant: inset),
                child.trailingAnchor.constraint(equalTo: guide.trailingAnchor, constant: -inset),
                child.bottomAnchor.constraint(equalTo: guide.bottomAnchor, constant: -inset),
            ])
        }
    } else if parentKind == "Box" {
        let stack = parent as! NSStackView
        stack.addArrangedSubview(child)
        ndBoxChildAttached(stack, child)
    } else if parentKind == "ScrollView" {
        let sv = parent as! NSScrollView
        let doc = sv.documentView!
        doc.subviews.forEach { $0.removeFromSuperview() }
        child.translatesAutoresizingMaskIntoConstraints = false
        doc.addSubview(child)
        NSLayoutConstraint.activate([
            child.leadingAnchor.constraint(equalTo: doc.leadingAnchor),
            child.trailingAnchor.constraint(equalTo: doc.trailingAnchor),
            child.topAnchor.constraint(equalTo: doc.topAnchor),
            child.bottomAnchor.constraint(equalTo: doc.bottomAnchor),
        ])
    } else if parentKind == "TabView" {
        guard let tabs = ndTabViewController(for: parent) else { return }
        tabs.addTabViewItem(ndMakeTabViewItem(child, label: attachedTabLabel, icon: attachedTabIcon))
    } else if parentKind == "Grid" {
        let grid = parent as! NSGridView
        ndGridPlace(grid, child, row: attachedGridRow, column: attachedGridColumn, rowSpan: attachedGridRowSpan, columnSpan: attachedGridColumnSpan)
    } else if parentKind == "SplitView" {
        let split = parent as! NSSplitView
        let controller = ndSplitViewController(for: split)!
        var realChild = child
        if let pane = child as? NDToolbarPaneView {
            ndToolbarPaneAttachedToSplit(pane, split: split, slot: attachedSlot)
            realChild = pane.contentView ?? child
        }
        let vc = ndMakePaneViewController(realChild)
        if attachedSlot == "sidebar" {
            let item = NSSplitViewItem(sidebarWithViewController: vc)
            item.minimumThickness = 180
            if let fraction = splitViewSidebarFraction[ObjectIdentifier(split)] {
                item.preferredThicknessFraction = fraction
                controller.pendingSidebarFraction = fraction
            }
            item.canCollapse = true
            item.isCollapsed = splitViewCollapsed[ObjectIdentifier(split)] ?? false
            controller.insertSplitViewItem(item, at: 0)
        } else if attachedSlot == "list" {
            let item = NSSplitViewItem(contentListWithViewController: vc)
            item.minimumThickness = 240
            item.canCollapse = true
            item.automaticallyAdjustsSafeAreaInsets = true
            item.titlebarSeparatorStyle = .none
            if let fraction = splitViewListFraction[ObjectIdentifier(split)] {
                item.preferredThicknessFraction = fraction
                controller.pendingListFraction = fraction
            }
            let insertIndex = controller.splitViewItems.first?.behavior == .sidebar ? 1 : 0
            controller.insertSplitViewItem(item, at: insertIndex)
        } else if attachedSlot == "inspector" {
            let item = NSSplitViewItem(inspectorWithViewController: vc)
            item.minimumThickness = 220
            item.canCollapse = true
            controller.addSplitViewItem(item)
        } else {
            let item = NSSplitViewItem(viewController: vc)
            item.automaticallyAdjustsSafeAreaInsets = true
            item.titlebarSeparatorStyle = .none // the scroll edge effect replaces the rule
            if let last = controller.splitViewItems.last, last.behavior == .inspector {
                controller.insertSplitViewItem(item, at: controller.splitViewItems.count - 1)
            } else {
                controller.addSplitViewItem(item)
            }
        }
        controller.splitViewItemsChanged()
    } else if parentKind == "HeaderBar" {
        ndHeaderBarPack(parent as! NDHeaderBarView, child, slot: attachedSlot)
    } else if parentKind == "ToolbarView" {
        let pane = parent as! NDToolbarPaneView
        ndToolbarPanePack(pane, child, slot: attachedSlot)
        if attachedSlot == "top" || attachedSlot == "bottom" {
            let styles = attachedSlot == "top" ? ndToolbarPaneTopBarStyles : ndToolbarPaneBottomBarStyles
            if (styles[ObjectIdentifier(pane)] ?? "flat") != "flat" {
                ndApplyToolbarStrip(child, enabled: true)
            }
        }
    } else if parentKind == "Menubar" {
        ndMenuAppendChild(parent, child)
    } else if parentKind == "Menu" {
        ndMenuAppendChild(parent, child)
    } else if parentKind == "SettingsGroup" {
        let group = parent as! NDSettingsGroupView
        group.appendReactView(child)
    } else if parentKind == "Row" {
        ndRowPack(parent as! NDRowView, child, slot: attachedSlot)
    } else if parentKind == "Clamp" {
        (parent as! NDClampView).setClampChild(child)
    } else if parentKind == "MenuButton" {
        ndMenuOwnerAppend(parent, child)
    } else if parentKind == "SplitButton" {
        ndMenuOwnerAppend(parent, child)
    } else if parentKind == "Popover" {
        ndPopoverSetChild(parent, child)
    } else if parentKind == "Expander" {
        (parent as! NDExpanderView).setContentChild(child)
    } else if parentKind == "StatusPage" {
        ndStatusPagePack(parent, child, before: nil)
    } else if parentKind == "ToastOverlay" {
        ndToastOverlaySetChild(parent, child)
    } else if parentKind == "TrayItem" {
        ndMenuOwnerAppend(parent, child)
    } else if parentKind == "Paned" {
        let split = parent as! NSSplitView
        split.addSubview(child)
        ndPanedController(for: split)?.reapplyFraction()
    } else if parentKind == "Dialog" {
        ndOverlaySetContent(parent, child)
    } else if parentKind == "Sheet" {
        ndOverlaySetContent(parent, child)
    } else {
        FileHandle.standardError.write("ND_WARN append to non-container kind=\(parentKind)\n".data(using: .utf8)!)
    }
}

func ndInsertBefore(_ parent: NSView, _ parentKind: String, _ child: NSView, _ before: NSView?, _ attachedJson: String) {
    // nil `before` degenerates to append everywhere (matches the M4 hand-written contract).
    guard let before = before else { return ndAppendChild(parent, parentKind, child, attachedJson) }
    // Cross-cutting (M15): Popover/TrayItem/overlay children are position-independent.
    if ndPopoverStructuralAttach(child, parent) { return }
    if ndTrayItemStructuralAttach(child) { return }
    if ndOverlayStructuralAttach(child, parent) { return }
    let attached = parseProps(attachedJson)
    let attachedTabLabel = propStr(attached, "tabLabel") ?? ""
    let attachedTabIcon = propStr(attached, "tabIcon") ?? ""
    let attachedGridRow = propInt(attached, "gridRow") ?? 0
    let attachedGridColumn = propInt(attached, "gridColumn") ?? 0
    let attachedGridRowSpan = propInt(attached, "gridRowSpan") ?? 1
    let attachedGridColumnSpan = propInt(attached, "gridColumnSpan") ?? 1
    let attachedSlot = propStr(attached, "slot") ?? "content"
    if parentKind == "Box" {
        let stack = parent as! NSStackView
        if stack.arrangedSubviews.contains(child) { stack.removeArrangedSubview(child) }
        let idx = stack.arrangedSubviews.firstIndex(of: before) ?? stack.arrangedSubviews.count
        stack.insertArrangedSubview(child, at: idx)
        ndBoxChildAttached(stack, child)
    } else if parentKind == "TabView" {
        guard let tabs = ndTabViewController(for: parent) else { return }
        let item = ndMakeTabViewItem(child, label: attachedTabLabel, icon: attachedTabIcon)
        let idx = tabs.tabViewItems.firstIndex { $0.viewController?.view === before } ?? tabs.tabViewItems.count
        tabs.insertTabViewItem(item, at: idx)
    } else if parentKind == "Grid" {
        // Grid children are position-addressed; sibling order is irrelevant.
        let grid = parent as! NSGridView
        ndGridPlace(grid, child, row: attachedGridRow, column: attachedGridColumn, rowSpan: attachedGridRowSpan, columnSpan: attachedGridColumnSpan)
    } else if parentKind == "SplitView" {
        let split = parent as! NSSplitView
        let controller = ndSplitViewController(for: split)!
        var realChild = child
        if let pane = child as? NDToolbarPaneView {
            ndToolbarPaneAttachedToSplit(pane, split: split, slot: attachedSlot)
            realChild = pane.contentView ?? child
        }
        let vc = ndMakePaneViewController(realChild)
        if attachedSlot == "sidebar" {
            let item = NSSplitViewItem(sidebarWithViewController: vc)
            item.minimumThickness = 180
            if let fraction = splitViewSidebarFraction[ObjectIdentifier(split)] {
                item.preferredThicknessFraction = fraction
                controller.pendingSidebarFraction = fraction
            }
            item.canCollapse = true
            item.isCollapsed = splitViewCollapsed[ObjectIdentifier(split)] ?? false
            controller.insertSplitViewItem(item, at: 0)
        } else if attachedSlot == "list" {
            let item = NSSplitViewItem(contentListWithViewController: vc)
            item.minimumThickness = 240
            item.canCollapse = true
            item.automaticallyAdjustsSafeAreaInsets = true
            item.titlebarSeparatorStyle = .none
            if let fraction = splitViewListFraction[ObjectIdentifier(split)] {
                item.preferredThicknessFraction = fraction
                controller.pendingListFraction = fraction
            }
            let insertIndex = controller.splitViewItems.first?.behavior == .sidebar ? 1 : 0
            controller.insertSplitViewItem(item, at: insertIndex)
        } else if attachedSlot == "inspector" {
            let item = NSSplitViewItem(inspectorWithViewController: vc)
            item.minimumThickness = 220
            item.canCollapse = true
            controller.addSplitViewItem(item)
        } else {
            let item = NSSplitViewItem(viewController: vc)
            item.automaticallyAdjustsSafeAreaInsets = true
            item.titlebarSeparatorStyle = .none // the scroll edge effect replaces the rule
            if let last = controller.splitViewItems.last, last.behavior == .inspector {
                controller.insertSplitViewItem(item, at: controller.splitViewItems.count - 1)
            } else {
                controller.addSplitViewItem(item)
            }
        }
        controller.splitViewItemsChanged()
    } else if parentKind == "HeaderBar" {
        ndHeaderBarPack(parent as! NDHeaderBarView, child, slot: attachedSlot)
    } else if parentKind == "ToolbarView" {
        let pane = parent as! NDToolbarPaneView
        ndToolbarPanePack(pane, child, slot: attachedSlot)
        if attachedSlot == "top" || attachedSlot == "bottom" {
            let styles = attachedSlot == "top" ? ndToolbarPaneTopBarStyles : ndToolbarPaneBottomBarStyles
            if (styles[ObjectIdentifier(pane)] ?? "flat") != "flat" {
                ndApplyToolbarStrip(child, enabled: true)
            }
        }
    } else if parentKind == "Menubar" {
        ndMenuAppendChild(parent, child)
    } else if parentKind == "Menu" {
        ndMenuAppendChild(parent, child)
    } else if parentKind == "SettingsGroup" {
        let group = parent as! NDSettingsGroupView
        group.insertReactView(child, before: before)
    } else if parentKind == "Row" {
        ndRowPack(parent as! NDRowView, child, slot: attachedSlot)
    } else if parentKind == "MenuButton" {
        ndMenuOwnerAppend(parent, child)
    } else if parentKind == "SplitButton" {
        ndMenuOwnerAppend(parent, child)
    } else if parentKind == "StatusPage" {
        ndStatusPagePack(parent, child, before: before)
    } else if parentKind == "TrayItem" {
        ndMenuOwnerAppend(parent, child)
    } else if parentKind == "Paned" {
        let split = parent as! NSSplitView
        split.addSubview(child, positioned: .below, relativeTo: before)
        ndPanedController(for: split)?.reapplyFraction()
    } else {
        // single-child containers: insertBefore degenerates to appendChild.
        ndAppendChild(parent, parentKind, child, attachedJson)
    }
}

func ndRemoveChild(_ parent: NSView, _ parentKind: String, _ child: NSView) {
    // Cross-cutting (M15): detach an anchored Popover / tear down a
    // TrayItem's NSStatusItem / close an unmounted overlay — none of the
    // three was ever a layout child.
    if ndPopoverStructuralDetach(child, parent) { return }
    if ndTrayItemStructuralDetach(child) { return }
    if ndOverlayStructuralDetach(child, parent) { return }
    // Cross-cutting: deregister a torn-down `<paned>`'s controller (no-op
    // unless `child` is itself a Paned's outer split view) — additive, not a
    // short-circuit, since the split view still needs the ordinary
    // removeFromSuperview dispatch below.
    ndPanedTeardown(child)
    if parentKind == "Window" {
        if ndIsMenuNode(child) { return } // M13: menubar detach is a no-op (mainMenu rebuilt on next change)
        if let pane = child as? NDToolbarPaneView {
            ndToolbarPaneDetachedFromSplit(pane) // same unregister path as the split arm
            let content = pane.contentView ?? pane
            content.removeFromSuperview()
            return
        }
        if let split = child as? NSSplitView, let controller = ndSplitViewController(for: split),
           let window = parent.window ?? gWindow, window.contentViewController === controller {
            window.contentViewController = nil
            window.contentView = parent
        } else if let overlay = child as? NDToastOverlayView, let split = overlay.ndEmbeddedSplit,
                  let controller = ndSplitViewController(for: split),
                  let window = overlay.ndHostWindow ?? parent.window ?? gWindow, window.contentViewController === controller {
            window.contentViewController = nil
            window.contentView = parent
            overlay.ndHostWindow = nil
        } else {
            child.removeFromSuperview()
        }
    } else if parentKind == "Box" {
        let stack = parent as! NSStackView
        stack.removeArrangedSubview(child)
        ndBoxChildDetached(stack, child)
        child.removeFromSuperview()
    } else if parentKind == "ScrollView" {
        let sv = parent as! NSScrollView
        if child.superview === sv.documentView { child.removeFromSuperview() }
    } else if parentKind == "TabView" {
        guard let tabs = ndTabViewController(for: parent) else { return }
        if let item = tabs.tabViewItems.first(where: { $0.viewController?.view === child }) {
            tabs.removeTabViewItem(item)
        }
    } else if parentKind == "Grid" {
        let grid = parent as! NSGridView
        ndGridRemove(grid, child)
    } else if parentKind == "SplitView" {
        let split = parent as! NSSplitView
        let controller = ndSplitViewController(for: split)!
        var realChild = child
        var paneItemHost: NSView? = nil
        if let pane = child as? NDToolbarPaneView {
            ndToolbarPaneDetachedFromSplit(pane)
            paneItemHost = pane.paneController?.view
            pane.paneController = nil
            realChild = pane.contentView ?? child
        }
        if let item = controller.splitViewItems.first(where: { $0.viewController.view === paneItemHost || $0.viewController.view === realChild || realChild.isDescendant(of: $0.viewController.view) }) {
            controller.removeSplitViewItem(item)
        } else {
            split.removeArrangedSubview(realChild)
            realChild.removeFromSuperview()
        }
    } else if parentKind == "HeaderBar" {
        ndHeaderBarUnpack(parent as! NDHeaderBarView, child)
    } else if parentKind == "ToolbarView" {
        ndToolbarPaneUnpack(parent as! NDToolbarPaneView, child)
    } else if parentKind == "Menubar" {
        ndMenuRemoveChild(parent, child)
    } else if parentKind == "Menu" {
        ndMenuRemoveChild(parent, child)
    } else if parentKind == "SettingsGroup" {
        let group = parent as! NDSettingsGroupView
        group.removeReactView(child)
    } else if parentKind == "Row" {
        ndRowUnpack(parent as! NDRowView, child)
    } else if parentKind == "Clamp" {
        (parent as! NDClampView).clearClampChild(child)
    } else if parentKind == "MenuButton" {
        ndMenuOwnerRemove(parent, child)
    } else if parentKind == "SplitButton" {
        ndMenuOwnerRemove(parent, child)
    } else if parentKind == "Popover" {
        ndPopoverClearChild(parent, child)
    } else if parentKind == "Expander" {
        (parent as! NDExpanderView).clearContentChild(child)
    } else if parentKind == "StatusPage" {
        ndStatusPageUnpack(parent, child)
    } else if parentKind == "ToastOverlay" {
        ndToastOverlayClearChild(parent, child)
    } else if parentKind == "TrayItem" {
        ndMenuOwnerRemove(parent, child)
    } else if parentKind == "Paned" {
        let split = parent as! NSSplitView
        child.removeFromSuperview()
        ndPanedController(for: split)?.reapplyFraction()
    } else if parentKind == "Dialog" {
        ndOverlayClearContent(parent, child)
    } else if parentKind == "Sheet" {
        ndOverlayClearContent(parent, child)
    } else {
        FileHandle.standardError.write("ND_WARN remove from non-container kind=\(parentKind)\n".data(using: .utf8)!)
    }
}
